-- AceDecks -- exam prep and the voice tutor, in one paste.
--
-- The seven migrations dated 2026-09-06, concatenated in the order they must
-- run. Generated by scripts/build-sql-bundle.mjs from supabase/migrations/ --
-- edit those, not this.
--
-- Paste the whole file into the Supabase SQL editor and run it once. It is
-- safe to run more than once: every table and index is guarded with IF NOT
-- EXISTS, every insert is ON CONFLICT DO NOTHING, and the one UPDATE is
-- idempotent.
--
-- The ordering is load-bearing and fails SILENTLY if you shuffle it. File 01
-- creates the unique index that files 03 to 06 insert against, and an insert
-- against the old index drops rows through ON CONFLICT DO NOTHING without a
-- word -- which is exactly how a third of the SAT bank went missing. File 02
-- widens the question_type constraint the select-all questions need, and
-- gives each exam the configuration without which the engine cannot read its
-- own bank. Top to bottom, or not at all.
--
-- Every statement below was parsed with PostgreSQL's own grammar
-- (libpg_query) before this file was generated.

-- ======================================================================
-- PREFLIGHT
-- ======================================================================
--
-- Stops with one readable message instead of a cascade of failures if an
-- earlier migration was never applied. Not hypothetical:
-- 20260715_diagnostics_and_study_plans.sql shipped with an undoubled
-- apostrophe inside a string literal, so it could never have run against
-- Postgres. If this preflight stops you, that is why -- the file has now
-- been fixed, so apply it and the diagnostic migrations after it, then come
-- back here.

do $$
begin
  if to_regclass('public.exam_definitions') is null then
    raise exception 'AceDecks: table public.exam_definitions is missing.'
      using hint = 'Apply supabase/migrations/20260715_diagnostics_and_study_plans.sql (just fixed), then the diagnostic migrations up to 20260731, then re-run this bundle.';
  end if;

  if to_regclass('public.diagnostic_questions') is null then
    raise exception 'AceDecks: table public.diagnostic_questions is missing.'
      using hint = 'Apply supabase/migrations/20260715_diagnostics_and_study_plans.sql first, then re-run this bundle.';
  end if;

  if to_regclass('public.voice_sessions') is null then
    raise exception 'AceDecks: table public.voice_sessions is missing.'
      using hint = 'Apply supabase/migrations/20260902_voice_tutor_sessions.sql first, then re-run this bundle.';
  end if;
end
$$;


-- ======================================================================
-- FILE: 20260906_01_diagnostic_question_identity_fix.sql
-- ======================================================================

-- A question is its stimulus AND its stem, not its stem alone.
--
-- diagnostic_questions has carried a unique index on (exam_id,
-- md5(question_text)) since the diagnostics centre was built, and every seed
-- migration inserts with "on conflict ... do nothing". On most exams that is
-- fine. On the Digital SAT it is not, because the stem is boilerplate: every
-- words-in-context item asks "Which choice completes the text with the most
-- logical and precise word?" and the question is the passage above it.
--
-- So 32 of the 98 seeded SAT questions were silently discarded on insert.
-- Nothing errored. The migrations said 98 and the bank held 66 -- a third of
-- the Digital SAT bank has never existed in any deployed database, which is
-- why the Full Diagnostic was thin on Reading and Writing items.
--
-- Two changes:
--
--   1. Identity becomes the stimulus and the stem together. A separator that
--      cannot occur in either -- a unit separator, written as the constant
--      E'\x1f' rather than chr(31) so the index expression needs no
--      argument about function volatility -- sits between them, so a
--      stimulus ending where a stem begins cannot collide with the reverse
--      split.
--   2. The four SAT seeds are replayed under the new identity, which inserts
--      exactly the rows that were lost and does nothing for the rows that
--      landed. The originals are left untouched: a migration that has already
--      run somewhere is history, and rewriting it fixes nobody's database.
--
-- Safe to run more than once.

drop index if exists public.diagnostic_questions_exam_text_unique;

create unique index if not exists diagnostic_questions_exam_item_unique
  on public.diagnostic_questions (exam_id, md5(coalesce(stimulus, '') || E'\x1f' || question_text));

comment on index public.diagnostic_questions_exam_item_unique is
  'Exact-duplicate guard. Keyed on stimulus AND question text: on the Digital SAT the stem is boilerplate and the item is the passage, so keying on the stem alone silently dropped a third of the bank.';

-- ============================================================
-- The Digital SAT bank, replayed under the corrected identity
-- ============================================================

insert into public.diagnostic_questions
  (exam_id, section, domain, skill, difficulty, question_type, stimulus, question_text, answer_choices, correct_answer, explanation, status, source_type, reviewed_at)
select e.id, v.section, v.domain, v.skill, v.difficulty, v.question_type, v.stimulus, v.question_text, v.answer_choices::jsonb, v.correct_answer, v.explanation, 'published', 'human_authored', now()
from public.exam_definitions e
cross join (values

  ('reading_writing', 'Craft and Structure', 'Words in context', 'easy', 'multiple_choice',
