set disclaimer = 'AceDecks GRE-style practice. Original questions written to the ETS published test structure. Not affiliated with or endorsed by ETS, and not official GRE content.'
where slug = 'gre';

update public.exam_definitions
set disclaimer = 'AceDecks SAT-style practice. Original questions written to College Board''s published Digital SAT specification. Not affiliated with or endorsed by College Board, and not official SAT content. Score estimates are AceDecks own and are not College Board scores.'
where slug = 'digital-sat';

comment on column public.exam_definitions.configuration is
  'The exam shape, parsed by lib/examBlueprint.ts: section order, module sizes and timings, the quick-mode sample, each section score scale, and how sections combine into a composite. Changing an exam structure is an edit here, not a code deploy.';


-- ======================================================================
-- FILE: 20260906_03_act_question_bank.sql
-- ======================================================================

-- An original ACT-style question bank.
--
-- Every item below was written for this migration. None of it reproduces,
-- paraphrases, or is derived from a real ACT item -- those are copyrighted
-- and secure, and shipping them would put AceDecks and every school that
-- buys Classroom at risk. What IS copied is the published specification:
-- the four sections, their domains, the question formats and the pacing.
-- A specification is public; a question bank is not.
--
-- Written to the enhanced ACT: English 50/35, Math 45/50, Reading 36/40,
-- and the optional Science 40/40. Domain names are ACT's own reporting
-- categories, so a student who sees "Production of Writing" here sees the
-- same words on a real score report.
--
-- Where a Reading or Science question needs a passage, the passage is
-- stored on the question rather than in a table of its own. That looks like
-- duplication and is deliberate: the bank picker selects items
-- independently, so two questions from one passage will usually not appear
-- together, and an item that cannot be answered without a sibling it may
-- never be shown alongside is a broken item.
--
-- Idempotent through the (exam_id, stimulus + question_text) unique index
-- created in 20260906_01. That ordering is not incidental: nearly every
-- Conventions of Standard English item here shares the stem "Which choice
-- makes the sentence conform to the conventions of Standard English?", and
-- under the old stem-only index ten of these sixty rows would have been
-- silently discarded on insert -- the same bug that cost the SAT bank a
-- third of its questions.

insert into public.diagnostic_questions
  (exam_id, section, domain, skill, difficulty, question_type, stimulus, question_text, answer_choices, correct_answer, explanation, status, source_type, reviewed_at)
select e.id, v.section, v.domain, v.skill, v.difficulty, v.question_type, v.stimulus, v.question_text, v.answer_choices::jsonb, v.correct_answer, v.explanation, 'published', 'human_authored', now()
from public.exam_definitions e
cross join (values

  -- ========================= English =========================
  -- Conventions of Standard English

  ('english', 'Conventions of Standard English', 'Punctuation', 'easy', 'multiple_choice',
    'The observatory, which sits at the highest point in the county ______ attracts astronomers from three neighboring states.',
    'Which choice makes the sentence conform to the conventions of Standard English?',
    '[{"id":"A","text":"county, attracts"},{"id":"B","text":"county; attracts"},{"id":"C","text":"county: attracts"},{"id":"D","text":"county attracts"}]',
    'A', 'The clause "which sits at the highest point in the county" is nonessential and already opens with a comma, so it must close with one. A semicolon or colon would need an independent clause after it, and omitting the punctuation leaves the interrupting clause unclosed.'),

  ('english', 'Conventions of Standard English', 'Subject-verb agreement', 'easy', 'multiple_choice',
    'The collection of fossils donated by the retired geologist ______ now the centerpiece of the museum''s new wing.',
    'Which choice makes the sentence conform to the conventions of Standard English?',
    '[{"id":"A","text":"are"},{"id":"B","text":"is"},{"id":"C","text":"were"},{"id":"D","text":"have been"}]',
    'B', 'The subject is "collection", which is singular; "of fossils" is a prepositional phrase and cannot govern the verb. Every plural option agrees with "fossils" rather than with the actual subject.'),

  ('english', 'Conventions of Standard English', 'Pronoun agreement', 'easy', 'multiple_choice',
    'Neither of the two candidates had finished ______ closing statement when the moderator called time.',
    'Which choice makes the sentence conform to the conventions of Standard English?',
    '[{"id":"A","text":"their"},{"id":"B","text":"his or her"},{"id":"C","text":"its"},{"id":"D","text":"they''re"}]',
    'B', '"Neither" is singular, so it takes a singular pronoun, and the candidates are people rather than things. "Their" is plural, "its" is for things, and "they''re" is a contraction of "they are".'),

  ('english', 'Conventions of Standard English', 'Sentence boundaries', 'medium', 'multiple_choice',
    'The storm knocked out power for six days ______ the bakery on Third Street never closed once.',
    'Which choice makes the sentence conform to the conventions of Standard English?',
    '[{"id":"A","text":"days, the bakery"},{"id":"B","text":"days, but the bakery"},{"id":"C","text":"days the bakery"},{"id":"D","text":"days, and however the bakery"}]',
    'B', 'Two independent clauses joined by a comma alone is a comma splice, and joined by nothing is a run-on. A comma plus the coordinating conjunction "but" joins them correctly and matches the contrast between the two facts.'),

  ('english', 'Conventions of Standard English', 'Modifiers', 'medium', 'multiple_choice',
    'Rusted through and missing two rungs, ______',
    'Which choice completes the sentence so that the modifier is not dangling?',
    '[{"id":"A","text":"the inspector condemned the fire escape."},{"id":"B","text":"the fire escape was condemned by the inspector."},{"id":"C","text":"condemning the fire escape was necessary."},{"id":"D","text":"it was necessary to condemn the fire escape."}]',
    'B', 'The opening phrase describes the fire escape, so the fire escape must be the subject that follows. In A the inspector is rusted through; in C and D the subject is an abstraction, which the phrase cannot describe.'),

  ('english', 'Conventions of Standard English', 'Verb tense', 'medium', 'multiple_choice',
    'By the time the archivists opened the crate, the letters inside ______ untouched for nearly a century.',
    'Which choice makes the sentence conform to the conventions of Standard English?',
    '[{"id":"A","text":"sit"},{"id":"B","text":"have sat"},{"id":"C","text":"had sat"},{"id":"D","text":"will have sat"}]',
    'C', 'The letters sat before the archivists opened the crate, and both events are in the past, so the earlier one takes the past perfect. The present perfect in B would connect the sitting to now rather than to the opening.'),

  ('english', 'Conventions of Standard English', 'Punctuation', 'hard', 'multiple_choice',
    'The recipe calls for three ingredients the cook did not have ______ saffron, buttermilk, and a preserved lemon.',
    'Which choice makes the sentence conform to the conventions of Standard English?',
    '[{"id":"A","text":"have, saffron"},{"id":"B","text":"have: saffron"},{"id":"C","text":"have; saffron"},{"id":"D","text":"have saffron"}]',
    'B', 'A colon introduces a list that specifies what the preceding independent clause referred to. A semicolon requires an independent clause after it, and a bare comma before a three-item list of this kind leaves the list unintroduced.'),

  ('english', 'Conventions of Standard English', 'Parallel structure', 'hard', 'multiple_choice',
    'The apprenticeship required her to draft blueprints, to survey the site, and ______',
    'Which choice completes the sentence with parallel structure?',
    '[{"id":"A","text":"supervising the pour."},{"id":"B","text":"she supervised the pour."},{"id":"C","text":"to supervise the pour."},{"id":"D","text":"the supervision of the pour."}]',
    'C', 'The first two items are infinitive phrases, so the third must be one as well. A gerund, a clause and a noun phrase each break the series.'),

  -- Production of Writing

  ('english', 'Production of Writing', 'Transitions', 'easy', 'multiple_choice',
    'The new filtration system removes almost every contaminant the old one missed. ______ it uses roughly a third less electricity to do it.',
    'Which transition best fits the relationship between the two sentences?',
    '[{"id":"A","text":"Nevertheless,"},{"id":"B","text":"Better still,"},{"id":"C","text":"By contrast,"},{"id":"D","text":"For instance,"}]',
    'B', 'The second sentence adds a further advantage, so an additive transition fits. "Nevertheless" and "By contrast" signal opposition, and "For instance" signals an example, which the electricity figure is not.'),

  ('english', 'Production of Writing', 'Adding and deleting', 'medium', 'multiple_choice',
    'A paragraph about the decline of urban bee populations ends: "Beekeepers in the city reported losing 38 percent of their hives last winter, the worst rate on record." The writer is considering adding the sentence: "Honey has been produced in the region since at least the 1840s."',
    'Should the writer make this addition?',
    '[{"id":"A","text":"Yes, because it establishes the historical importance of local beekeeping."},{"id":"B","text":"Yes, because it explains why hive losses were unusually high."},{"id":"C","text":"No, because it introduces a detail unrelated to the paragraph''s focus on recent losses."},{"id":"D","text":"No, because it contradicts the statistic given in the previous sentence."}]',
    'C', 'The paragraph is about a recent, measured decline. The date honey production began is unrelated to that, so the sentence is a digression. It does not explain the losses and it contradicts nothing.'),

  ('english', 'Production of Writing', 'Organization', 'medium', 'multiple_choice',
    'A writer is arranging four sentences: (1) The results surprised even the researchers who designed the trial. (2) Volunteers walked for twenty minutes after each meal. (3) A recent study tested a very simple intervention. (4) Average post-meal blood sugar fell by nearly a fifth.',
    'Which order produces the most logical paragraph?',
    '[{"id":"A","text":"3, 2, 4, 1"},{"id":"B","text":"1, 3, 2, 4"},{"id":"C","text":"2, 3, 1, 4"},{"id":"D","text":"4, 1, 2, 3"}]',
    'A', 'The paragraph must introduce the study, describe what was done, report the result, then comment on it. Sentence 1 comments on results and so cannot come before them, which eliminates B and D; sentence 2 cannot open, since "Volunteers" has no antecedent yet.'),

  ('english', 'Production of Writing', 'Purpose', 'hard', 'multiple_choice',
    'A writer wants to end an essay about restoring a salt marsh by emphasizing that the work is not finished.',
    'Which choice best accomplishes that goal?',
    '[{"id":"A","text":"The marsh today is a remarkable sight, and the volunteers deserve every bit of the credit."},{"id":"B","text":"Three of the seven original channels now flow freely; the other four are still choked with fill."},{"id":"C","text":"Restoration projects like this one have been attempted in nine states."},{"id":"D","text":"The first shovel went into the ground on a cold morning in March."}]',
    'B', 'Only B names what remains undone, and does so with a specific figure. A closes on praise, C widens to other states, and D returns to the beginning of the project.'),

  -- Knowledge of Language

  ('english', 'Knowledge of Language', 'Word choice', 'easy', 'multiple_choice',
    'The committee''s report was so ______ that even the members who had written it struggled to summarize its recommendations.',
    'Which word best fits the context?',
    '[{"id":"A","text":"convoluted"},{"id":"B","text":"concise"},{"id":"C","text":"illuminating"},{"id":"D","text":"abbreviated"}]',
    'A', 'If the authors themselves could not summarize it, the report was tangled. "Concise" and "abbreviated" mean short, and "illuminating" means clarifying -- each the opposite of what the sentence describes.'),

  ('english', 'Knowledge of Language', 'Concision', 'medium', 'multiple_choice',
    'The reason the flight was delayed was because of the fact that a mechanical inspection ran long.',
    'Which revision is most concise while keeping the meaning?',
    '[{"id":"A","text":"The reason the flight was delayed was due to the fact that a mechanical inspection ran long."},{"id":"B","text":"The flight was delayed because a mechanical inspection ran long."},{"id":"C","text":"The reason for the flight delay was on account of a long mechanical inspection."},{"id":"D","text":"The flight, delayed, was because of a mechanical inspection running long."}]',
    'B', '"The reason ... was because" is redundant, and "the fact that" adds nothing. B states the cause once. C keeps the redundancy in different words, and D is ungrammatical.'),

  ('english', 'Knowledge of Language', 'Style and tone', 'medium', 'multiple_choice',
    'In a formal lab report: "The temperature readings from the second trial were ______ compared with the first."',
    'Which choice best maintains the tone of the report?',
    '[{"id":"A","text":"way off"},{"id":"B","text":"substantially lower"},{"id":"C","text":"kind of low"},{"id":"D","text":"a total mess"}]',
    'B', 'A lab report calls for precise, neutral language. The other three are conversational, and two of them are vague about direction as well as degree.'),

  ('english', 'Knowledge of Language', 'Word choice', 'hard', 'multiple_choice',
    'Although the treaty was signed with great ceremony, its provisions were ______ from the first week, and by spring neither side was pretending otherwise.',
    'Which word best fits the context?',
    '[{"id":"A","text":"flouted"},{"id":"B","text":"flaunted"},{"id":"C","text":"fostered"},{"id":"D","text":"formalized"}]',
    'A', 'To flout is to disregard openly, which is what the second clause describes. "Flaunt" means to display showily and is the classic confusion here; "fostered" and "formalized" both mean the treaty was being upheld.'),

  ('english', 'Conventions of Standard English', 'Apostrophes', 'medium', 'multiple_choice',
    'Both of the ______ engines were rebuilt over the winter, and the fleet returned to service in April.',
    'Which choice makes the sentence conform to the conventions of Standard English?',
    '[{"id":"A","text":"ferries''"},{"id":"B","text":"ferry''s"},{"id":"C","text":"ferries"},{"id":"D","text":"ferrys''"}]',
    'A', '"Both" establishes more than one ferry, and the engines belong to them, so this is a plural possessive: ferries becomes ferries with an apostrophe after the s. B is singular possessive, C is a plain plural, and "ferrys" is not a spelling of the plural.'),

  ('english', 'Production of Writing', 'Transitions', 'hard', 'multiple_choice',
    'Wind turbines kill an estimated hundreds of thousands of birds each year in the United States. ______ buildings and domestic cats are each responsible for losses two to three orders of magnitude larger.',
    'Which transition best fits the relationship between the two sentences?',
    '[{"id":"A","text":"Consequently,"},{"id":"B","text":"For perspective,"},{"id":"C","text":"Similarly,"},{"id":"D","text":"In other words,"}]',
    'B', 'The second sentence supplies a comparison that reframes the size of the first figure. It is not a consequence, not a restatement, and not a parallel case -- the whole point is the difference in scale.'),

  ('english', 'Conventions of Standard English', 'Punctuation', 'easy', 'multiple_choice',
    'The mechanic explained that the noise was harmless ______ a loose heat shield rattling against the exhaust.',
    'Which choice makes the sentence conform to the conventions of Standard English?',
    '[{"id":"A","text":"harmless, a loose"},{"id":"B","text":"harmless. A loose"},{"id":"C","text":"harmless; a loose"},{"id":"D","text":"harmless and a loose"}]',
    'A', 'The phrase after the blank renames "the noise" and is not an independent clause, so a comma is correct. A period or semicolon would leave a fragment standing alone, and "and" would suggest a second, separate thing.'),

  ('english', 'Knowledge of Language', 'Concision', 'easy', 'multiple_choice',
    'At this point in time, the museum is currently closed for renovations.',
    'Which revision is most concise while keeping the meaning?',
    '[{"id":"A","text":"At this point in time, the museum is closed for renovations."},{"id":"B","text":"The museum is currently closed for renovations at this time."},{"id":"C","text":"The museum is closed for renovations."},{"id":"D","text":"Currently, at this point, the museum is closed for renovations."}]',
    'C', '"At this point in time" and "currently" say the same thing, and the present tense already says it a third time. Only C removes all of the redundancy.'),

  -- ========================= Math =========================

  ('math', 'Integrating Essential Skills', 'Percentages', 'easy', 'multiple_choice',
    null,
    'A jacket is marked down from $80 to $68. By what percent was the price reduced?',
    '[{"id":"A","text":"12%"},{"id":"B","text":"15%"},{"id":"C","text":"17.6%"},{"id":"D","text":"20%"}]',
    'B', 'The reduction is $12, and 12/80 = 0.15, so 15 percent. Choice A is the dollar amount mistaken for a percent, and C divides by the new price instead of the original.'),

  ('math', 'Preparing for Higher Math', 'Linear equations', 'easy', 'multiple_choice',
    null,
    'If 5x - 3 = 2x + 12, what is the value of x?',
    '[{"id":"A","text":"3"},{"id":"B","text":"5"},{"id":"C","text":"7"},{"id":"D","text":"9"}]',
    'B', 'Subtracting 2x from both sides gives 3x - 3 = 12, so 3x = 15 and x = 5.'),

  ('math', 'Integrating Essential Skills', 'Rates', 'easy', 'multiple_choice',
    null,
    'A printer produces 14 pages per minute. How many minutes does it take to print 385 pages?',
    '[{"id":"A","text":"22.5"},{"id":"B","text":"25"},{"id":"C","text":"27.5"},{"id":"D","text":"32"}]',
    'C', 'Time equals total pages divided by the rate: 385 / 14 = 27.5 minutes. Multiplying instead of dividing gives a number in the thousands, and the units are the check -- pages divided by pages-per-minute leaves minutes.'),

  ('math', 'Preparing for Higher Math', 'Geometry', 'easy', 'multiple_choice',
    null,
    'A right triangle has legs of length 9 and 12. What is the length of its hypotenuse?',
    '[{"id":"A","text":"13"},{"id":"B","text":"15"},{"id":"C","text":"21"},{"id":"D","text":"25"}]',
    'B', '81 + 144 = 225, and the square root of 225 is 15. Choice C adds the legs instead of using the Pythagorean theorem.'),

  ('math', 'Preparing for Higher Math', 'Quadratics', 'medium', 'multiple_choice',
    null,
    'What are the solutions to x^2 - 5x - 14 = 0?',
    '[{"id":"A","text":"x = -2 and x = 7"},{"id":"B","text":"x = 2 and x = -7"},{"id":"C","text":"x = -1 and x = 14"},{"id":"D","text":"x = 1 and x = -14"}]',
    'A', 'The expression factors as (x - 7)(x + 2), so x = 7 or x = -2. Choice B has the signs of both roots reversed, which multiplies to -14 but sums to -5 rather than +5.'),

  ('math', 'Preparing for Higher Math', 'Functions', 'medium', 'multiple_choice',
    null,
    'If f(x) = 3x^2 - 2x + 1, what is f(-2)?',
    '[{"id":"A","text":"9"},{"id":"B","text":"11"},{"id":"C","text":"17"},{"id":"D","text":"-15"}]',
    'C', '3(-2)^2 = 12, then -2(-2) = +4, plus 1 gives 17. Choice D comes from squaring after multiplying, treating 3(-2)^2 as (3 times -2)^2 with the wrong sign handling.'),

  ('math', 'Preparing for Higher Math', 'Statistics and probability', 'medium', 'multiple_choice',
    null,
    'A bag holds 4 red, 6 blue, and 5 green marbles. One marble is drawn and not replaced, and it is blue. What is the probability the next marble drawn is also blue?',
    '[{"id":"A","text":"6/15"},{"id":"B","text":"5/14"},{"id":"C","text":"6/14"},{"id":"D","text":"5/15"}]',
    'B', 'After one blue is removed there are 5 blue marbles among 14 remaining. Choice C forgets to reduce the blue count, and A ignores the removal entirely.'),

  ('math', 'Modeling', 'Linear models', 'medium', 'multiple_choice',
    null,
    'A gym charges a $45 joining fee plus $28 per month. Which equation gives the total cost C in dollars after m months?',
    '[{"id":"A","text":"C = 45m + 28"},{"id":"B","text":"C = 28m + 45"},{"id":"C","text":"C = 73m"},{"id":"D","text":"C = 45 + 28 + m"}]',
    'B', 'The monthly charge is the rate and so multiplies m; the joining fee is paid once and is the constant. Choice A reverses the two, and C charges the joining fee every month.'),

  ('math', 'Preparing for Higher Math', 'Trigonometry', 'medium', 'multiple_choice',
    null,
    'In a right triangle, the angle A satisfies sin A = 3/5. What is cos A, given that A is acute?',
    '[{"id":"A","text":"3/4"},{"id":"B","text":"4/5"},{"id":"C","text":"5/4"},{"id":"D","text":"4/3"}]',
    'B', 'With opposite 3 and hypotenuse 5, the adjacent leg is 4 by the Pythagorean theorem, so cos A = 4/5. Choice A is tan A and D is its reciprocal.'),

  ('math', 'Integrating Essential Skills', 'Proportions', 'medium', 'multiple_choice',
    null,
    'A map uses a scale of 1 inch to 24 miles. Two towns are 3.5 inches apart on the map. How many miles apart are they?',
    '[{"id":"A","text":"68"},{"id":"B","text":"72"},{"id":"C","text":"84"},{"id":"D","text":"96"}]',
    'C', '3.5 times 24 is 84 miles. Choice B multiplies by 3 and D by 4.'),

  ('math', 'Preparing for Higher Math', 'Number and quantity', 'hard', 'multiple_choice',
    null,
    'If i is the imaginary unit, what is (3 + 2i)(1 - 4i)?',
    '[{"id":"A","text":"11 - 10i"},{"id":"B","text":"-5 - 10i"},{"id":"C","text":"3 - 8i"},{"id":"D","text":"11 + 14i"}]',
    'A', 'Expanding gives 3 - 12i + 2i - 8i^2. Since i^2 = -1, the last term is +8, so the result is 11 - 10i. Choice B treats i^2 as +1.'),

  ('math', 'Preparing for Higher Math', 'Geometry', 'hard', 'multiple_choice',
    null,
    'A circle has the equation x^2 + y^2 - 6x + 8y = 0. What is its radius?',
    '[{"id":"A","text":"5"},{"id":"B","text":"7"},{"id":"C","text":"10"},{"id":"D","text":"25"}]',
    'A', 'Completing the square gives (x - 3)^2 + (y + 4)^2 = 9 + 16 = 25, so the radius is the square root of 25, which is 5. Choice D reports the square of the radius.'),

  ('math', 'Modeling', 'Exponential models', 'hard', 'multiple_choice',
    null,
    'A culture of 500 bacteria doubles every 3 hours. Which expression gives the population after t hours?',
    '[{"id":"A","text":"500 * 2^(3t)"},{"id":"B","text":"500 * 2^(t/3)"},{"id":"C","text":"500 * 3^(t/2)"},{"id":"D","text":"500 + 2^(t/3)"}]',
    'B', 'One doubling happens per 3 hours, so the exponent counts doublings: t/3. Choice A doubles three times an hour, and C swaps the base with the interval.'),

  ('math', 'Preparing for Higher Math', 'Systems', 'hard', 'student_produced_response',
    null,
    'The system 2x + 3y = 31 and x - y = 3 has exactly one solution. What is the value of y?',
    null, '5', 'From the second equation x = y + 3. Substituting gives 2(y + 3) + 3y = 31, so 5y + 6 = 31, 5y = 25, and y = 5.'),

  ('math', 'Integrating Essential Skills', 'Averages', 'hard', 'student_produced_response',
    null,
    'A student has scores of 82, 91, and 78 on three tests. What score on a fourth test would make the average of all four exactly 85?',
    null, '89', 'A mean of 85 across four tests requires a total of 340. The first three total 251, so the fourth must be 89.'),

  ('math', 'Preparing for Higher Math', 'Functions', 'hard', 'multiple_choice',
    null,
    'The function g is defined by g(x) = 2(x - 4)^2 + 7. What is the minimum value of g?',
    '[{"id":"A","text":"-4"},{"id":"B","text":"4"},{"id":"C","text":"7"},{"id":"D","text":"15"}]',
    'C', 'A squared term is never negative, so the smallest value of 2(x - 4)^2 is 0, reached at x = 4, leaving g = 7. Choice B reports the x value at which the minimum occurs rather than the minimum itself.'),

  -- ========================= Reading =========================

  ('reading', 'Key Ideas and Details', 'Main idea', 'easy', 'multiple_choice',
    'For thirty years my grandmother kept a ledger of every plant she put in the ground: the date, the weather, the corner of the garden, and, in a column she headed simply "Result", one of three words -- thrived, struggled, died. She did not garden by feel. She gardened by evidence, and the evidence was mostly of failure. Nine notebooks sit on my shelf now, and what strikes me is not the successes, which are few, but how patiently she recorded the losses.',
    'The passage is primarily concerned with:',
    '[{"id":"A","text":"the varieties of plants best suited to a difficult climate"},{"id":"B","text":"the narrator''s grandmother''s methodical documentation of her gardening, including its failures"},{"id":"C","text":"the narrator''s regret at never having learned to garden"},{"id":"D","text":"the practical advantages of keeping written records in any hobby"}]',
    'B', 'The passage describes the ledger, its columns, and the narrator''s reaction to the record of failure. It names no plant varieties, expresses no regret about the narrator''s own gardening, and generalizes to no other hobby.'),

  ('reading', 'Craft and Structure', 'Word meaning in context', 'medium', 'multiple_choice',
    'For thirty years my grandmother kept a ledger of every plant she put in the ground: the date, the weather, the corner of the garden, and, in a column she headed simply "Result", one of three words -- thrived, struggled, died. She did not garden by feel. She gardened by evidence, and the evidence was mostly of failure. Nine notebooks sit on my shelf now, and what strikes me is not the successes, which are few, but how patiently she recorded the losses.',
    'As it is used in the passage, the word "patiently" most nearly means:',
    '[{"id":"A","text":"calmly, without irritation"},{"id":"B","text":"slowly, at an unhurried pace"},{"id":"C","text":"persistently, without giving up the record"},{"id":"D","text":"quietly, without telling anyone"}]',
    'C', 'The narrator is struck by thirty years of recording losses, so the word carries the sense of persistence over time. The passage says nothing about her mood, her speed, or her secrecy.'),

  ('reading', 'Integration of Knowledge and Ideas', 'Inference', 'medium', 'multiple_choice',
    'For thirty years my grandmother kept a ledger of every plant she put in the ground: the date, the weather, the corner of the garden, and, in a column she headed simply "Result", one of three words -- thrived, struggled, died. She did not garden by feel. She gardened by evidence, and the evidence was mostly of failure. Nine notebooks sit on my shelf now, and what strikes me is not the successes, which are few, but how patiently she recorded the losses.',
    'It can reasonably be inferred from the passage that the grandmother considered a failed planting to be:',
    '[{"id":"A","text":"a reason to abandon that corner of the garden"},{"id":"B","text":"information worth keeping"},{"id":"C","text":"an embarrassment best left unrecorded"},{"id":"D","text":"proof that her methods were unsound"}]',
    'B', 'She recorded failures as carefully as successes and gardened "by evidence", which treats a failure as data. Nothing suggests she abandoned ground, hid results, or doubted her approach.'),

  ('reading', 'Key Ideas and Details', 'Detail', 'easy', 'multiple_choice',
    'Between 1870 and 1910 the number of public libraries in the United States rose from fewer than 200 to more than 3,000. Andrew Carnegie funded roughly half of the new buildings, but his grants came with a condition that is often forgotten: the town had to supply the site and commit public money -- usually a tenth of the construction cost, every year -- to running the library once it opened. Towns that would not make the commitment did not get the building, and several dozen refused.',
    'According to the passage, Carnegie''s grants required a town to:',
    '[{"id":"A","text":"repay the construction cost over ten years"},{"id":"B","text":"provide the site and commit annual public funding for operations"},{"id":"C","text":"name the library after Carnegie"},{"id":"D","text":"match his grant dollar for dollar before construction began"}]',
    'B', 'The passage states the two conditions directly: supply the site, and commit public money each year to running it. Repayment, naming and dollar-for-dollar matching are not mentioned.'),

  ('reading', 'Integration of Knowledge and Ideas', 'Author purpose', 'medium', 'multiple_choice',
    'Between 1870 and 1910 the number of public libraries in the United States rose from fewer than 200 to more than 3,000. Andrew Carnegie funded roughly half of the new buildings, but his grants came with a condition that is often forgotten: the town had to supply the site and commit public money -- usually a tenth of the construction cost, every year -- to running the library once it opened. Towns that would not make the commitment did not get the building, and several dozen refused.',
    'The author includes the final sentence primarily to:',
    '[{"id":"A","text":"show that the condition was a real constraint rather than a formality"},{"id":"B","text":"criticize the towns that declined the grants"},{"id":"C","text":"explain why library construction slowed after 1910"},{"id":"D","text":"suggest that Carnegie regretted imposing the condition"}]',
    'A', 'Naming towns that refused demonstrates that the requirement had teeth. The sentence passes no judgement on those towns, says nothing about the period after 1910, and reports nothing about Carnegie''s feelings.'),

  ('reading', 'Craft and Structure', 'Text structure', 'hard', 'multiple_choice',
    'Between 1870 and 1910 the number of public libraries in the United States rose from fewer than 200 to more than 3,000. Andrew Carnegie funded roughly half of the new buildings, but his grants came with a condition that is often forgotten: the town had to supply the site and commit public money -- usually a tenth of the construction cost, every year -- to running the library once it opened. Towns that would not make the commitment did not get the building, and several dozen refused.',
    'Which choice best describes the structure of the passage?',
    '[{"id":"A","text":"A statistic, then a common misunderstanding corrected, then evidence that the correction matters"},{"id":"B","text":"A claim, then two counterarguments, then a concession"},{"id":"C","text":"A chronological account of one library''s construction"},{"id":"D","text":"A comparison of philanthropic models in two countries"}]',
    'A', 'The passage opens with growth figures, notes a condition that is "often forgotten", and closes with towns that refused -- evidence the forgotten condition had consequences. There is no counterargument, no single library narrative and no second country.'),

  ('reading', 'Key Ideas and Details', 'Main idea', 'medium', 'multiple_choice',
    'The blue whale''s heart is the size of a small car, and for a long time that fact was the whole story: enormous animal, enormous organ. Then researchers managed to attach a heart-rate monitor to a wild blue whale and found something nobody had predicted. At the surface its heart beat about 37 times a minute. On a deep dive it fell to 2. Not slow -- 2. The organ is not merely large; it operates across a range no other mammalian heart approaches.',
    'The main point of the passage is that the blue whale''s heart is remarkable for:',
    '[{"id":"A","text":"its size alone"},{"id":"B","text":"the range of rates at which it can operate"},{"id":"C","text":"how difficult it was to monitor"},{"id":"D","text":"how closely it resembles other mammalian hearts"}]',
    'B', 'The passage sets up size as "the whole story" only to replace it: the finding is the span from 37 beats a minute to 2. The difficulty of monitoring is background, and the closing sentence says the opposite of D.'),

  ('reading', 'Craft and Structure', 'Rhetorical effect', 'hard', 'multiple_choice',
    'The blue whale''s heart is the size of a small car, and for a long time that fact was the whole story: enormous animal, enormous organ. Then researchers managed to attach a heart-rate monitor to a wild blue whale and found something nobody had predicted. At the surface its heart beat about 37 times a minute. On a deep dive it fell to 2. Not slow -- 2. The organ is not merely large; it operates across a range no other mammalian heart approaches.',
    'The sentence "Not slow -- 2." primarily serves to:',
    '[{"id":"A","text":"correct an error in the preceding sentence"},{"id":"B","text":"insist that the reader register how extreme the figure is"},{"id":"C","text":"introduce a measurement taken at a different depth"},{"id":"D","text":"concede that the monitoring may have been inaccurate"}]',
    'B', 'The fragment repeats the number rather than adding information, which is a way of refusing to let the reader skim past it. It corrects nothing, adds no new measurement and concedes nothing.'),

  ('reading', 'Integration of Knowledge and Ideas', 'Evidence', 'hard', 'multiple_choice',
    'The blue whale''s heart is the size of a small car, and for a long time that fact was the whole story: enormous animal, enormous organ. Then researchers managed to attach a heart-rate monitor to a wild blue whale and found something nobody had predicted. At the surface its heart beat about 37 times a minute. On a deep dive it fell to 2. Not slow -- 2. The organ is not merely large; it operates across a range no other mammalian heart approaches.',
    'Which detail from the passage most directly supports the claim in the final sentence?',
    '[{"id":"A","text":"The heart is the size of a small car."},{"id":"B","text":"Researchers attached a monitor to a wild blue whale."},{"id":"C","text":"The rate falls from about 37 at the surface to 2 on a deep dive."},{"id":"D","text":"The finding was not predicted."}]',
    'C', 'The final sentence claims an unmatched operating range, and only the pair of rates establishes a range. Size supports the claim the sentence is arguing against, and the other two details describe the study rather than its result.'),

  ('reading', 'Key Ideas and Details', 'Detail', 'medium', 'multiple_choice',
    'Sourdough is not a recipe so much as a relationship. The starter is a living culture of wild yeast and lactic acid bacteria, and it eats on a schedule: fed too little, it sours and weakens; fed too much, it never develops flavor. Bakers speak of a starter''s "mood" and they are not being whimsical. A culture kept at 24 degrees Celsius behaves measurably differently from the same culture kept at 18, and the bread records the difference.',
    'According to the passage, a starter that is fed too much will:',
    '[{"id":"A","text":"sour and weaken"},{"id":"B","text":"fail to develop flavor"},{"id":"C","text":"change temperature"},{"id":"D","text":"stop rising entirely"}]',
    'B', 'The passage pairs each error with its consequence: too little food sours and weakens it, too much leaves it without flavor. The other options either swap the two or state something the passage does not.'),

  ('reading', 'Craft and Structure', 'Word meaning in context', 'medium', 'multiple_choice',
    'Sourdough is not a recipe so much as a relationship. The starter is a living culture of wild yeast and lactic acid bacteria, and it eats on a schedule: fed too little, it sours and weakens; fed too much, it never develops flavor. Bakers speak of a starter''s "mood" and they are not being whimsical. A culture kept at 24 degrees Celsius behaves measurably differently from the same culture kept at 18, and the bread records the difference.',
    'The author puts the word "mood" in quotation marks primarily to:',
    '[{"id":"A","text":"question whether bakers understand their own craft"},{"id":"B","text":"mark it as bakers'' shorthand for a real, measurable variation"},{"id":"C","text":"indicate that the word is being quoted from a specific source"},{"id":"D","text":"signal that the passage is about to change subject"}]',
    'B', 'The next sentence insists the bakers "are not being whimsical" and then gives temperature evidence, so the marks flag borrowed vocabulary for something genuine. The passage defends the bakers rather than questioning them.'),

  ('reading', 'Integration of Knowledge and Ideas', 'Inference', 'hard', 'multiple_choice',
    'Sourdough is not a recipe so much as a relationship. The starter is a living culture of wild yeast and lactic acid bacteria, and it eats on a schedule: fed too little, it sours and weakens; fed too much, it never develops flavor. Bakers speak of a starter''s "mood" and they are not being whimsical. A culture kept at 24 degrees Celsius behaves measurably differently from the same culture kept at 18, and the bread records the difference.',
    'The passage most strongly suggests that two bakers using identical ingredients and identical feeding schedules could still produce different bread because:',
    '[{"id":"A","text":"wild yeast varies from region to region"},{"id":"B","text":"the temperature at which each starter is kept may differ"},{"id":"C","text":"one baker may be more experienced than the other"},{"id":"D","text":"lactic acid bacteria die at room temperature"}]',
    'B', 'Ingredients and schedule are held fixed by the question, and the only other variable the passage names is temperature, which it says produces measurable differences. Regional yeast, experience and bacterial death are never mentioned.'),

  -- ========================= Science =========================

  ('science', 'Interpretation of Data', 'Reading a table', 'easy', 'multiple_choice',
    'Students measured how long a 50 mL sample of water took to reach 80 degrees Celsius on a hot plate at four power settings.

Setting | Power (W) | Time to 80 C (s)
1       | 250       | 412
2       | 500       | 196
3       | 750       | 141
4       | 1000      | 103',
    'Based on the table, as power setting increases, the time to reach 80 degrees Celsius:',
    '[{"id":"A","text":"increases only"},{"id":"B","text":"decreases only"},{"id":"C","text":"increases, then decreases"},{"id":"D","text":"remains constant"}]',
    'B', 'The times fall from 412 to 196 to 141 to 103 seconds, decreasing at every step.'),

  ('science', 'Interpretation of Data', 'Interpolation', 'medium', 'multiple_choice',
    'Students measured how long a 50 mL sample of water took to reach 80 degrees Celsius on a hot plate at four power settings.

Setting | Power (W) | Time to 80 C (s)
1       | 250       | 412
2       | 500       | 196
3       | 750       | 141
4       | 1000      | 103',
    'If the experiment were repeated at 625 W, the time to reach 80 degrees Celsius would most likely be closest to:',
    '[{"id":"A","text":"110 s"},{"id":"B","text":"165 s"},{"id":"C","text":"250 s"},{"id":"D","text":"400 s"}]',
    'B', '625 W lies between 500 W and 750 W, so the time should lie between 196 s and 141 s. Only 165 s falls in that interval.'),

  ('science', 'Evaluation of Models, Inferences, and Experimental Results', 'Proportional reasoning', 'hard', 'multiple_choice',
    'Students measured how long a 50 mL sample of water took to reach 80 degrees Celsius on a hot plate at four power settings.

Setting | Power (W) | Time to 80 C (s)
1       | 250       | 412
2       | 500       | 196
3       | 750       | 141
4       | 1000      | 103',
    'A student claims that doubling the power always halves the heating time exactly. The data most strongly support which evaluation of that claim?',
    '[{"id":"A","text":"Supported, because 500 W took less than half the time of 250 W"},{"id":"B","text":"Not supported, because 500 W took slightly less than half the time of 250 W and 1000 W took slightly more than half the time of 500 W"},{"id":"C","text":"Supported, because time decreases whenever power increases"},{"id":"D","text":"Not supported, because time increased at one of the settings"}]',
    'B', 'Half of 412 is 206 and the measured value is 196, so the first doubling beat the prediction; half of 196 is 98 and the measured value at 1000 W is 103, so the second doubling missed it. The relationship is close to inverse but not exact. Time never increased, which rules out D, and mere direction is not the claim, which rules out C.'),

  ('science', 'Scientific Investigation', 'Experimental design', 'medium', 'multiple_choice',
    'Experiment 1: Seedlings of one species were grown for 21 days under lamps of four colors -- red, blue, green, and white -- with all lamps set to the same intensity. Mean height was recorded.
Experiment 2: The same procedure was repeated, but each pot also received one of three fertilizer concentrations.

Color  | Exp 1 mean height (cm)
Red    | 12.4
Blue   | 15.1
Green  | 6.8
White  | 14.7',
    'In Experiment 1, keeping every lamp at the same intensity was necessary in order to:',
    '[{"id":"A","text":"ensure that the seedlings received enough total light to survive"},{"id":"B","text":"make light color the only variable differing among the groups"},{"id":"C","text":"reduce the total time the experiment required"},{"id":"D","text":"allow the results to be compared with Experiment 2"}]',
    'B', 'Holding intensity constant isolates color as the manipulated variable. If intensity varied with color, a height difference could be caused by either, and the experiment would answer neither question.'),

  ('science', 'Interpretation of Data', 'Comparing results', 'easy', 'multiple_choice',
    'Experiment 1: Seedlings of one species were grown for 21 days under lamps of four colors -- red, blue, green, and white -- with all lamps set to the same intensity. Mean height was recorded.
Experiment 2: The same procedure was repeated, but each pot also received one of three fertilizer concentrations.

Color  | Exp 1 mean height (cm)
Red    | 12.4
Blue   | 15.1
Green  | 6.8
White  | 14.7',
    'According to Experiment 1, which lamp color produced the shortest seedlings?',
    '[{"id":"A","text":"Red"},{"id":"B","text":"Blue"},{"id":"C","text":"Green"},{"id":"D","text":"White"}]',
    'C', 'Green produced a mean height of 6.8 cm, lower than every other color.'),

  ('science', 'Evaluation of Models, Inferences, and Experimental Results', 'Hypothesis evaluation', 'hard', 'multiple_choice',
    'Experiment 1: Seedlings of one species were grown for 21 days under lamps of four colors -- red, blue, green, and white -- with all lamps set to the same intensity. Mean height was recorded.
Experiment 2: The same procedure was repeated, but each pot also received one of three fertilizer concentrations.

Color  | Exp 1 mean height (cm)
Red    | 12.4
Blue   | 15.1
Green  | 6.8
White  | 14.7',
    'A researcher hypothesizes that chlorophyll absorbs green light poorly. Which result from Experiment 1 is most consistent with that hypothesis?',
    '[{"id":"A","text":"Blue produced the tallest seedlings."},{"id":"B","text":"Green produced seedlings roughly half the height of those under white light."},{"id":"C","text":"Red and white produced similar heights."},{"id":"D","text":"All four groups grew for the same 21 days."}]',
    'B', 'Poor absorption of green light means less usable energy and therefore less growth, which is exactly the deficit the green group shows against the white control. A is consistent with strong blue absorption but does not bear on green, and C and D say nothing about green at all.'),

  ('science', 'Scientific Investigation', 'Controls', 'medium', 'multiple_choice',
    'A student tested whether a commercial rust inhibitor slows corrosion. Ten identical iron nails were coated with inhibitor and left in salt water; ten uncoated nails were left in fresh water. After two weeks the coated nails showed less rust.',
    'The student''s conclusion that the inhibitor slows corrosion is weakened primarily because:',
    '[{"id":"A","text":"only ten nails were used in each group"},{"id":"B","text":"the two groups differed in the water used as well as in the coating"},{"id":"C","text":"two weeks is not long enough for iron to rust"},{"id":"D","text":"rust was assessed by appearance rather than by mass"}]',
    'B', 'Two variables changed at once, and salt water is the more corrosive of the two -- so the coated nails rusted less despite the harsher condition, which the design cannot separate from the coating. Sample size and measurement method are secondary, and iron visibly rusts well within two weeks.'),

  ('science', 'Interpretation of Data', 'Reading a graph description', 'medium', 'multiple_choice',
    'Dissolved oxygen was measured at four depths in a lake in July and again in January.

Depth (m) | July DO (mg/L) | January DO (mg/L)
0         | 8.9            | 12.6
5         | 8.1            | 12.4
10        | 4.2            | 12.0
20        | 0.6            | 11.5',
    'The difference between July and January dissolved oxygen is greatest at which depth?',
    '[{"id":"A","text":"0 m"},{"id":"B","text":"5 m"},{"id":"C","text":"10 m"},{"id":"D","text":"20 m"}]',
    'D', 'At 20 m the difference is 11.5 minus 0.6, or 10.9 mg/L, larger than 3.7, 4.3 and 7.8 at the shallower depths.'),

  ('science', 'Evaluation of Models, Inferences, and Experimental Results', 'Inference', 'hard', 'multiple_choice',
    'Dissolved oxygen was measured at four depths in a lake in July and again in January.

Depth (m) | July DO (mg/L) | January DO (mg/L)
0         | 8.9            | 12.6
5         | 8.1            | 12.0
10        | 4.2            | 11.8
20        | 0.6            | 11.5',
    'The January measurements differ from the July measurements most importantly in that in January:',
    '[{"id":"A","text":"oxygen is nearly uniform with depth"},{"id":"B","text":"oxygen falls sharply below 5 m"},{"id":"C","text":"oxygen is lowest at the surface"},{"id":"D","text":"oxygen exceeds 15 mg/L at every depth"}]',
    'A', 'The January values run 12.6, 12.0, 11.8, 11.5 -- a spread of about 1 mg/L across 20 m, against a July spread of more than 8. The sharp drop below 5 m is the July pattern, not January''s.'),

  ('science', 'Interpretation of Data', 'Trend identification', 'easy', 'multiple_choice',
    'A chemist measured the solubility of a salt in water at several temperatures.

Temperature (C) | Solubility (g per 100 mL)
10              | 21
20              | 32
30              | 46
40              | 63
50              | 84',
    'Based on the table, solubility at 25 degrees Celsius would most likely be closest to:',
    '[{"id":"A","text":"26 g per 100 mL"},{"id":"B","text":"39 g per 100 mL"},{"id":"C","text":"46 g per 100 mL"},{"id":"D","text":"55 g per 100 mL"}]',
    'B', '25 C lies between 20 C and 30 C, so solubility lies between 32 and 46 g per 100 mL. Only 39 falls in that interval.'),

  ('science', 'Scientific Investigation', 'Extending a procedure', 'medium', 'multiple_choice',
    'A chemist measured the solubility of a salt in water at several temperatures.

Temperature (C) | Solubility (g per 100 mL)
10              | 21
20              | 32
30              | 46
40              | 63
50              | 84',
    'To test whether the relationship between temperature and solubility continues above 50 degrees Celsius, the chemist should:',
    '[{"id":"A","text":"repeat the measurement at 50 degrees Celsius several more times"},{"id":"B","text":"measure solubility at 60 and 70 degrees Celsius using the same procedure"},{"id":"C","text":"measure solubility of a different salt at the same temperatures"},{"id":"D","text":"measure solubility at 5 degrees Celsius"}]',
    'B', 'The question is about behaviour above 50 C, so the procedure must be extended to temperatures above 50 C. Repeating an existing point tests precision, a different salt tests a different substance, and 5 C extends the range in the wrong direction.'),

  ('science', 'Evaluation of Models, Inferences, and Experimental Results', 'Conflicting viewpoints', 'hard', 'multiple_choice',
    'Scientist 1 argues that the megafauna of North America died out primarily because of rapid climate warming at the end of the last glacial period, which fragmented the habitats large herbivores depended on.
Scientist 2 argues that human hunting was the primary cause, noting that extinctions on several continents track the arrival of humans more closely than they track any climate signal.',
    'Which finding, if confirmed, would most weaken Scientist 2''s argument?',
    '[{"id":"A","text":"Butchery marks on mammoth bones are found at several sites in North America."},{"id":"B","text":"On a continent where humans arrived thousands of years before the warming, megafauna persisted until the warming began."},{"id":"C","text":"Human populations grew quickly after the megafauna declined."},{"id":"D","text":"Some large herbivores survived in isolated regions for several thousand more years."}]',
    'B', 'Scientist 2 rests on extinctions tracking human arrival. A continent where humans arrived long before and the animals survived until the climate changed breaks exactly that correlation. A supports Scientist 2, C is ambiguous about direction, and D is compatible with either account.')

) as v(section, domain, skill, difficulty, question_type, stimulus, question_text, answer_choices, correct_answer, explanation)
where e.slug = 'act'
on conflict (exam_id, md5(coalesce(stimulus, '') || E'\x1f' || question_text)) do nothing;

-- Now, and only now, the ACT becomes available: there is something behind
-- the card. The status flip lives here rather than in the definitions
-- migration so an exam can never be switched on with an empty bank.
update public.exam_definitions
set status = 'available'
where slug = 'act'
  and exists (
    select 1 from public.diagnostic_questions q
    where q.exam_id = exam_definitions.id and q.status = 'published'
  );


-- ======================================================================
-- FILE: 20260906_04_nclex_rn_question_bank.sql
-- ======================================================================

-- An original NCLEX-RN-style question bank.
--
-- /exams has advertised NCLEX since it was written, and until now clicking
-- it went to a page whose only button went to /home. There was not an
-- exam_definitions row, let alone a question.
--
-- Every item below was written for this migration. None of it reproduces,
-- paraphrases or is derived from any NCSBN item -- those are secure, and a
-- product that shipped them would deserve everything that followed. What is
-- taken from NCSBN is the published 2026 test plan: the eight content areas,
-- their share of the exam, and the six steps of the Clinical Judgement
-- Measurement Model. A test plan is public; an item bank is not.
--
-- Domain names are the content areas exactly as the test plan words them,
-- including "Safety and Infection Prevention and Control", which the 2026
-- plan renamed from "Safety and Infection Control". A candidate who sees a
-- category here should see the same words in their own review book.
--
-- Item counts follow the plan's percentages rather than being spread evenly:
-- Pharmacological and Parenteral Therapies is the largest single area on the
-- real exam and is the largest here.
--
-- Two things every rationale does, because on this exam they are the whole
-- point: it says WHY the right option is right in terms of a principle the
-- candidate can reuse, and it says why the tempting wrong one is wrong.
-- "Maslow" and "ABCs" and "acute over chronic" are the reusable parts; the
-- specific patient is not.
--
-- AceDecks is exam preparation. Nothing here is clinical advice, and no
-- score here predicts a pass.
--
-- Idempotent through the (exam_id, stimulus + question_text) unique index.

insert into public.diagnostic_questions
  (exam_id, section, domain, skill, difficulty, question_type, stimulus, question_text, answer_choices, correct_answer, explanation, status, source_type, reviewed_at)
select e.id, v.section, v.domain, v.skill, v.difficulty, v.question_type, v.stimulus, v.question_text, v.answer_choices::jsonb, v.correct_answer, v.explanation, 'published', 'human_authored', now()
from public.exam_definitions e
cross join (values

  -- ============== Management of Care ==============

  ('nclex_rn', 'Management of Care', 'Prioritization', 'easy', 'multiple_choice',
    null,
    'A nurse begins a shift with four assigned clients. Which client should the nurse assess first?',
    '[{"id":"A","text":"A client who is two hours postoperative and reports incisional pain rated 6 out of 10"},{"id":"B","text":"A client with new-onset shortness of breath and an oxygen saturation of 88 percent on room air"},{"id":"C","text":"A client scheduled for discharge who has questions about a new medication"},{"id":"D","text":"A client with a chronic pressure injury due for a dressing change"}]',
    'B', 'Airway and breathing come before everything else. A saturation of 88 percent with new shortness of breath is an oxygenation problem that will worsen without intervention. The postoperative pain is expected and treatable but not immediately life-threatening, the discharge teaching can wait, and a chronic wound is stable by definition. The reusable principle: acute beats chronic, and within acute, the ABCs decide the order.'),

  ('nclex_rn', 'Management of Care', 'Delegation', 'easy', 'multiple_choice',
    null,
    'Which task is appropriate for a registered nurse to delegate to unlicensed assistive personnel?',
    '[{"id":"A","text":"Assessing a client''s lung sounds before ambulation"},{"id":"B","text":"Teaching a client how to use an incentive spirometer"},{"id":"C","text":"Measuring and recording vital signs for a stable client"},{"id":"D","text":"Evaluating a client''s response to a new pain medication"}]',
    'C', 'Delegation transfers a task, never the nursing process. Assessment, teaching and evaluation all require nursing judgement and cannot be delegated; measuring vital signs on a stable client is a routine, predictable task with a clear expected outcome. The reusable test: if the task requires judging what the finding means, it stays with the nurse.'),

  ('nclex_rn', 'Management of Care', 'Informed consent', 'medium', 'multiple_choice',
    null,
    'A client scheduled for surgery tells the nurse, "I signed the form, but I still do not understand what they are actually removing." What should the nurse do first?',
    '[{"id":"A","text":"Explain the surgical procedure to the client in simple terms"},{"id":"B","text":"Notify the surgeon that the client has questions about the procedure"},{"id":"C","text":"Reassure the client that the surgeon will explain everything beforehand"},{"id":"D","text":"Document that the client is anxious and continue preparing for surgery"}]',
    'B', 'Informed consent is the responsibility of the provider performing the procedure; the nurse witnesses the signature and confirms understanding. A client who does not understand has not given informed consent, so the surgeon must return. Explaining the procedure oversteps the nurse''s role, and reassurance and documentation both leave an invalid consent in place.'),

  ('nclex_rn', 'Management of Care', 'Prioritization', 'medium', 'multiple_choice',
    null,
    'A nurse receives report on four clients. Which client requires the most immediate attention?',
    '[{"id":"A","text":"A client with a potassium level of 6.8 mEq/L"},{"id":"B","text":"A client with a hemoglobin of 9.2 g/dL"},{"id":"C","text":"A client with a temperature of 38.1 degrees Celsius"},{"id":"D","text":"A client with a blood glucose of 210 mg/dL"}]',
    'A', 'A potassium of 6.8 mEq/L is severe hyperkalemia and carries an immediate risk of lethal dysrhythmia -- it is a cardiac emergency, not a laboratory abnormality. The other three are all abnormal and all need attention, but none of them will stop a heart in the next few minutes. The reusable principle: rank abnormal values by how fast they kill, not by how far they are from normal.'),

  ('nclex_rn', 'Management of Care', 'Scope of practice', 'medium', 'multiple_choice',
    null,
    'A registered nurse is assigning clients on a medical unit that includes a licensed practical nurse. Which client is most appropriate to assign to the LPN?',
    '[{"id":"A","text":"A client admitted one hour ago who needs an initial admission assessment"},{"id":"B","text":"A client with stable heart failure who needs daily weights and oral medications"},{"id":"C","text":"A client receiving a first dose of intravenous antibiotic"},{"id":"D","text":"A client whose plan of care needs revision after a change in condition"}]',
    'B', 'An LPN cares for stable clients with predictable outcomes. The initial admission assessment, the first dose of a medication that could cause a reaction, and revising a care plan all require RN assessment and judgement. Stable heart failure with routine weights and oral medication is exactly the predictable case an LPN manages.'),

  ('nclex_rn', 'Management of Care', 'Advocacy', 'medium', 'multiple_choice',
    null,
    'A client with decision-making capacity refuses a blood transfusion for religious reasons despite a hemoglobin of 6.5 g/dL. What is the nurse''s most appropriate action?',
    '[{"id":"A","text":"Administer the transfusion because the client''s life is at risk"},{"id":"B","text":"Ask a family member to sign the consent instead"},{"id":"C","text":"Document the refusal, notify the provider, and support the client''s decision"},{"id":"D","text":"Explain that the refusal will be overridden by the hospital ethics committee"}]',
    'C', 'A client with capacity has the right to refuse any treatment, including one that is life-sustaining, and administering it anyway is battery. The nurse documents, informs the provider so alternatives can be discussed, and supports the client. A family member cannot consent for a client who has capacity, and no ethics committee overrides a capable refusal.'),

  ('nclex_rn', 'Management of Care', 'Continuity of care', 'hard', 'multiple_choice',
    null,
    'During handoff, the off-going nurse reports that a client "had a rough night." Which response by the receiving nurse is most appropriate?',
    '[{"id":"A","text":"“Thank you, I will keep an eye on them.”"},{"id":"B","text":"“Can you tell me specifically what happened and what was done about it?”"},{"id":"C","text":"“I will read the notes when I get a chance.”"},{"id":"D","text":"“Did the provider come to see the client?”"}]',
    'B', 'Handoff is the highest-risk moment in a hospital stay, and a vague summary is a communication failure the receiving nurse can still repair by asking for specifics: what happened, what was done, what the response was. Accepting the vagueness, deferring to the chart, or asking a single narrow question all leave the gap in place.'),

  ('nclex_rn', 'Management of Care', 'Confidentiality', 'hard', 'multiple_choice',
    null,
    'A client''s adult sibling telephones the unit and asks for an update on the client''s condition. What should the nurse do?',
    '[{"id":"A","text":"Provide a general update since the caller is an immediate family member"},{"id":"B","text":"Confirm whether the client has authorized the release of information to this person"},{"id":"C","text":"Refuse to acknowledge that the client is in the facility under any circumstances"},{"id":"D","text":"Transfer the call to the provider so that they can decide"}]',
    'B', 'Being a relative does not by itself authorize disclosure, so the nurse verifies whether this caller is someone the client has authorized. A blanket refusal to acknowledge that the client is in the facility goes further than the law requires and is only correct when the client has opted out of the directory; handing the call to the provider passes the problem along without solving it. The distinction worth keeping: protecting information is always required, pretending the client does not exist is not.'),

  ('nclex_rn', 'Management of Care', 'Prioritization', 'hard', 'multiple_response',
    null,
    'A charge nurse is preparing to evacuate a unit during a fire on an adjacent floor. Which clients should be moved first? Select all that apply.',
    '[{"id":"A","text":"An ambulatory client who can walk without assistance"},{"id":"B","text":"A client who can walk with a walker and standby assistance"},{"id":"C","text":"A client on a ventilator requiring manual bagging to move"},{"id":"D","text":"A client in skeletal traction"},{"id":"E","text":"A client sleeping after receiving a sedative"}]',
    'A,B', 'Evacuation moves ambulatory clients first, because each one moved frees a staff member and clears the corridor for the difficult transfers that follow. The ventilated client, the client in traction and the sedated client all require more staff and more time, and moving them first would strand the people who could have walked out unaided.'),

  ('nclex_rn', 'Management of Care', 'Referrals', 'easy', 'multiple_choice',
    null,
    'A client being discharged after a stroke has difficulty swallowing thin liquids. Which referral is most appropriate for the nurse to initiate?',
    '[{"id":"A","text":"Speech-language pathology"},{"id":"B","text":"Physical therapy"},{"id":"C","text":"Respiratory therapy"},{"id":"D","text":"Social work"}]',
    'A', 'Swallowing evaluation and dysphagia management belong to speech-language pathology. Physical therapy addresses mobility, respiratory therapy addresses ventilation and airway clearance, and social work addresses discharge resources -- all of which this client may also need, but none of which assesses a swallow.'),

  -- ============== Safety and Infection Prevention and Control ==============

  ('nclex_rn', 'Safety and Infection Prevention and Control', 'Transmission-based precautions', 'easy', 'multiple_choice',
    null,
    'A client is admitted with suspected pulmonary tuberculosis. Which precautions should the nurse implement?',
    '[{"id":"A","text":"Contact precautions in a private room"},{"id":"B","text":"Droplet precautions with a surgical mask"},{"id":"C","text":"Airborne precautions in a negative-pressure room with an N95 respirator"},{"id":"D","text":"Standard precautions only until culture results return"}]',
    'C', 'Tuberculosis spreads on droplet nuclei small enough to stay suspended in air, which is what makes it airborne rather than droplet: it needs a negative-pressure room and a fitted N95, not a surgical mask. Precautions are started on suspicion, not on confirmation, so waiting for cultures exposes everyone in the meantime.'),

  ('nclex_rn', 'Safety and Infection Prevention and Control', 'Hand hygiene', 'easy', 'multiple_choice',
    null,
    'A nurse is caring for a client with Clostridioides difficile infection. Which hand hygiene method should the nurse use after client contact?',
    '[{"id":"A","text":"Alcohol-based hand rub"},{"id":"B","text":"Soap and water"},{"id":"C","text":"Alcohol-based hand rub followed by gloves"},{"id":"D","text":"Antiseptic wipe"}]',
    'B', 'C. difficile forms spores, and alcohol does not kill spores -- it needs the physical removal that soap and running water provide. This is the reason a unit with a C. difficile outbreak switches to soap and water despite alcohol rub being faster and easier on the hands everywhere else.'),

  ('nclex_rn', 'Safety and Infection Prevention and Control', 'Fall prevention', 'easy', 'multiple_choice',
    null,
    'Which intervention is most effective for reducing the risk of falls in an older adult hospitalized client?',
    '[{"id":"A","text":"Keeping all four side rails raised at all times"},{"id":"B","text":"Ensuring the call light is within reach and the bed is in the lowest position"},{"id":"C","text":"Restricting the client to bed rest"},{"id":"D","text":"Applying a soft waist restraint at night"}]',
    'B', 'Reachable call light and a low bed reduce both the chance of an unassisted attempt and the injury if one happens. Four raised side rails are legally a restraint and increase injury when a client climbs over them; bed rest causes the deconditioning that makes the next fall likelier; and restraints are a last resort, never a first-line fall intervention.'),

  ('nclex_rn', 'Safety and Infection Prevention and Control', 'Medication safety', 'medium', 'multiple_choice',
    null,
    'A nurse is preparing to administer a medication and notices that the dose ordered is three times the usual adult dose. What should the nurse do?',
    '[{"id":"A","text":"Administer the dose as written since the provider ordered it"},{"id":"B","text":"Administer the usual dose instead and document the change"},{"id":"C","text":"Hold the medication and contact the prescriber to clarify the order"},{"id":"D","text":"Ask another nurse whether the dose seems reasonable and proceed if they agree"}]',
    'C', 'A nurse who recognizes a questionable order is obligated to clarify it before administering, and carrying out an order known to be unsafe transfers liability to the nurse. Changing the dose independently is prescribing, which is outside the nurse''s scope, and a colleague''s opinion does not substitute for the prescriber''s clarification.'),

  ('nclex_rn', 'Safety and Infection Prevention and Control', 'Personal protective equipment', 'medium', 'multiple_choice',
    null,
    'When removing personal protective equipment after caring for a client on contact precautions, which item should the nurse remove first?',
    '[{"id":"A","text":"Gown"},{"id":"B","text":"Gloves"},{"id":"C","text":"Mask"},{"id":"D","text":"Eye protection"}]',
    'B', 'Gloves are removed first because they are the most contaminated item and everything else is removed with hands that have touched them otherwise. The sequence runs gloves, then eye protection, then gown, then mask, and the mask comes off last because it is removed outside the room.'),

  ('nclex_rn', 'Safety and Infection Prevention and Control', 'Restraints', 'medium', 'multiple_choice',
    null,
    'A client in restraints requires assessment. How often should the nurse assess a client in violent or self-destructive behavioral restraints who is an adult?',
    '[{"id":"A","text":"Every 15 minutes"},{"id":"B","text":"Every 30 minutes"},{"id":"C","text":"Every hour"},{"id":"D","text":"Every 2 hours"}]',
    'A', 'Behavioral restraints for violent or self-destructive behavior carry the highest risk of injury and require the most frequent monitoring, at 15-minute intervals for an adult. Non-violent medical restraints are assessed less often, which is the distinction this question is built on -- the reason for the restraint sets the frequency, not the device.'),

  ('nclex_rn', 'Safety and Infection Prevention and Control', 'Client identification', 'medium', 'multiple_response',
    null,
    'Which identifiers may a nurse use to verify a client''s identity before administering a medication? Select all that apply.',
    '[{"id":"A","text":"The client''s full name"},{"id":"B","text":"The client''s date of birth"},{"id":"C","text":"The client''s room number"},{"id":"D","text":"The client''s medical record number"},{"id":"E","text":"The client''s bed position on the unit"}]',
    'A,B,D', 'Two identifiers are required and neither may be location-based, because a client can be moved. Name, date of birth and medical record number travel with the person; room number and bed position describe furniture, and using them is how a medication reaches the wrong client after a transfer.'),

  ('nclex_rn', 'Safety and Infection Prevention and Control', 'Surgical asepsis', 'hard', 'multiple_choice',
    null,
    'A nurse is setting up a sterile field and turns away briefly to answer a colleague''s question. What should the nurse do?',
    '[{"id":"A","text":"Continue using the field, since nothing visibly contaminated it"},{"id":"B","text":"Cover the field with a sterile drape and continue"},{"id":"C","text":"Consider the field contaminated and set up a new one"},{"id":"D","text":"Use only the center of the field, which remains sterile"}]',
    'C', 'A sterile field that is out of the setter''s sight is considered contaminated, whether or not anything is seen to touch it. Sterility is a status maintained by continuous observation, not a property judged by appearance -- which is why "it looked fine" is never the standard.'),

  -- ============== Health Promotion and Maintenance ==============

  ('nclex_rn', 'Health Promotion and Maintenance', 'Developmental stages', 'easy', 'multiple_choice',
    null,
    'A parent asks when an infant is typically able to sit without support. Which response by the nurse is accurate?',
    '[{"id":"A","text":"Around 2 months"},{"id":"B","text":"Around 4 months"},{"id":"C","text":"Around 6 to 8 months"},{"id":"D","text":"Around 12 months"}]',
    'C', 'Unsupported sitting typically appears between 6 and 8 months. At 2 months an infant is achieving head control, at 4 months rolling begins, and by 12 months most infants are pulling to stand and cruising -- so the earlier options describe skills that come before and the later one a skill that comes after.'),

  ('nclex_rn', 'Health Promotion and Maintenance', 'Prenatal care', 'medium', 'multiple_choice',
    null,
    'A client who is 32 weeks pregnant reports a severe headache, visual changes, and swelling of the hands and face. What is the nurse''s priority action?',
    '[{"id":"A","text":"Advise rest in a darkened room and recheck in the morning"},{"id":"B","text":"Assess blood pressure and notify the provider immediately"},{"id":"C","text":"Reassure the client that headaches are common in the third trimester"},{"id":"D","text":"Recommend an over-the-counter analgesic"}]',
    'B', 'Headache, visual changes and facial edema after 20 weeks are the classic warning signs of preeclampsia, which can progress to seizure. Blood pressure is the assessment that confirms the suspicion, and the provider must be told at once. Every other option treats a warning sign as a comfort problem and sends the client home with an untreated hypertensive disorder.'),

  ('nclex_rn', 'Health Promotion and Maintenance', 'Health screening', 'medium', 'multiple_choice',
    null,
    'A nurse is teaching a group of adults about colorectal cancer screening. Which statement indicates that teaching was effective?',
    '[{"id":"A","text":"“Screening should start at 45 for people at average risk.”"},{"id":"B","text":"“Screening is only needed if someone in my family had colon cancer.”"},{"id":"C","text":"“A colonoscopy is needed every year regardless of the result.”"},{"id":"D","text":"“Screening can stop as soon as I turn 50.”"}]',
    'A', 'Average-risk colorectal screening now begins at 45. Family history raises risk and may move the start earlier, but its absence does not remove the need; colonoscopy intervals depend on findings rather than being annual; and 50 is a starting point in older guidance, never a stopping point.'),

  ('nclex_rn', 'Health Promotion and Maintenance', 'Immunizations', 'easy', 'multiple_choice',
    null,
    'A client is scheduled to receive a live attenuated vaccine. Which finding in the client''s history requires the nurse to hold the vaccine and consult the provider?',
    '[{"id":"A","text":"A mild upper respiratory infection without fever"},{"id":"B","text":"Current pregnancy"},{"id":"C","text":"A history of vaccination two years ago"},{"id":"D","text":"A family member who is also pregnant"}]',
    'B', 'Live vaccines are contraindicated in pregnancy because of theoretical risk to the fetus. A mild illness without fever is not a reason to defer any vaccine, prior vaccination is history rather than contraindication, and a pregnant household contact is a precaution for some live vaccines but not a contraindication for the client.'),

  ('nclex_rn', 'Health Promotion and Maintenance', 'Aging', 'hard', 'multiple_choice',
    null,
    'Which finding in an 80-year-old client should the nurse investigate rather than attribute to normal aging?',
    '[{"id":"A","text":"Slower reaction time on a timed task"},{"id":"B","text":"New confusion developing over two days"},{"id":"C","text":"Reduced skin elasticity"},{"id":"D","text":"Decreased near vision requiring reading glasses"}]',
    'B', 'Acute confusion is delirium until proved otherwise, and it is a symptom of something else -- infection, hypoxia, a medication, a metabolic derangement -- not of being 80. Slowed reaction time, reduced skin elasticity and presbyopia are all expected age-related changes. The reusable rule: normal aging is gradual, and anything that appears over hours to days is a new problem.'),

  -- ============== Psychosocial Integrity ==============

  ('nclex_rn', 'Psychosocial Integrity', 'Therapeutic communication', 'easy', 'multiple_choice',
    null,
    'A client newly diagnosed with cancer says, "I do not think I can go through with this treatment." Which response by the nurse is most therapeutic?',
    '[{"id":"A","text":"“You have to do the treatment or the cancer will spread.”"},{"id":"B","text":"“Tell me what worries you most about the treatment.”"},{"id":"C","text":"“Everyone feels that way at first. You will be fine.”"},{"id":"D","text":"“Would you like me to call the chaplain?”"}]',
    'B', 'An open-ended invitation keeps the client talking and finds out what the fear actually is, which is the only route to addressing it. Warning about consequences uses fear as a lever, false reassurance dismisses the feeling, and offering a referral closes the conversation before anyone knows what is wrong.'),

  ('nclex_rn', 'Psychosocial Integrity', 'Suicide risk', 'medium', 'multiple_choice',
    null,
    'A client on an inpatient unit states, "I have figured out how to end things, and I have what I need at home." What is the nurse''s priority action?',
    '[{"id":"A","text":"Document the statement and continue the assessment"},{"id":"B","text":"Ask the client directly about the plan and initiate continuous observation"},{"id":"C","text":"Reassure the client that things will improve with treatment"},{"id":"D","text":"Notify the family so they can remove items from the home"}]',
    'B', 'A stated plan with available means is a high-risk disclosure requiring immediate safety measures, and asking directly about the plan does not increase risk -- that belief is the single most persistent myth on this topic. Documentation, reassurance and family notification all matter, but none of them keeps the client safe in the next five minutes.'),

  ('nclex_rn', 'Psychosocial Integrity', 'Substance withdrawal', 'medium', 'multiple_choice',
    null,
    'A client admitted 48 hours ago after stopping heavy daily alcohol use develops tremors, tachycardia, and visual hallucinations. What should the nurse anticipate?',
    '[{"id":"A","text":"That symptoms will resolve without intervention within a few hours"},{"id":"B","text":"That the client is experiencing alcohol withdrawal and requires urgent treatment"},{"id":"C","text":"That the client has an underlying psychotic disorder"},{"id":"D","text":"That the client is seeking additional medication"}]',
    'B', 'Tremor, tachycardia and hallucinations peaking around 48 hours after the last drink is the picture of alcohol withdrawal, which can progress to seizures and delirium tremens and carries real mortality untreated. Waiting it out is dangerous, and attributing the presentation to a psychiatric diagnosis or to drug-seeking misses a medical emergency.'),

  ('nclex_rn', 'Psychosocial Integrity', 'Grief', 'medium', 'multiple_choice',
    null,
    'A client whose spouse died three weeks ago tells the nurse, "I still set out two cups of coffee every morning." Which response is most appropriate?',
    '[{"id":"A","text":"“That sounds like it is time to talk to someone about your grief.”"},{"id":"B","text":"“It takes time. What is that morning like for you?”"},{"id":"C","text":"“You should try to change your routine to help you move on.”"},{"id":"D","text":"“Many people do that. It is completely normal.”"}]',
    'B', 'Three weeks out, this is ordinary grief rather than a complication, and the response both normalizes it briefly and opens the door to the client saying more. Suggesting professional help pathologizes normal grief, telling the client to change the routine directs behaviour nobody asked about, and closing with "completely normal" ends the conversation.'),

  ('nclex_rn', 'Psychosocial Integrity', 'De-escalation', 'hard', 'multiple_choice',
    null,
    'A client on a psychiatric unit is pacing, speaking loudly, and clenching their fists. What is the nurse''s most appropriate initial action?',
    '[{"id":"A","text":"Approach closely and place a hand on the client''s shoulder"},{"id":"B","text":"Speak calmly from a non-threatening distance and offer to talk in a quieter area"},{"id":"C","text":"Call security to place the client in restraints"},{"id":"D","text":"Ignore the behaviour so as not to reinforce it"}]',
    'B', 'De-escalation begins with a calm voice, personal space and an offer that gives the client a choice, and it works far more often than anything that follows it. Touch at this stage is likely to be read as a threat, restraints are a last resort after less restrictive measures fail, and ignoring escalating agitation lets it escalate.'),

  -- ============== Basic Care and Comfort ==============

  ('nclex_rn', 'Basic Care and Comfort', 'Nutrition', 'easy', 'multiple_choice',
    null,
    'A client is receiving continuous enteral tube feeding. Which nursing action best reduces the risk of aspiration?',
    '[{"id":"A","text":"Keeping the head of the bed elevated at least 30 degrees"},{"id":"B","text":"Flushing the tube with 30 mL of water every 8 hours"},{"id":"C","text":"Warming the formula before administration"},{"id":"D","text":"Changing the feeding bag every 48 hours"}]',
    'A', 'Elevating the head of the bed uses gravity to keep formula in the stomach and is the single most effective aspiration precaution during tube feeding. Flushing maintains patency, warming improves comfort, and bag changes control infection -- all worth doing, and none of them about aspiration.'),

  ('nclex_rn', 'Basic Care and Comfort', 'Mobility', 'easy', 'multiple_choice',
    null,
    'A nurse is teaching a client to use a cane after a right knee injury. Which instruction is correct?',
    '[{"id":"A","text":"“Hold the cane in your right hand and move it with your right leg.”"},{"id":"B","text":"“Hold the cane in your left hand and move it forward with your right leg.”"},{"id":"C","text":"“Hold the cane in whichever hand feels comfortable.”"},{"id":"D","text":"“Hold the cane in your right hand and move it with your left leg.”"}]',
    'B', 'A cane is held on the strong side and advances together with the weak leg, so weight is shared between the cane and the good leg while the injured one is loaded. Holding it on the injured side gives no offloading, and comfort is not the criterion -- the mechanics are.'),

  ('nclex_rn', 'Basic Care and Comfort', 'Elimination', 'medium', 'multiple_choice',
    null,
    'A client with an indwelling urinary catheter has no urine output for the past two hours. What should the nurse do first?',
    '[{"id":"A","text":"Irrigate the catheter with sterile saline"},{"id":"B","text":"Check the tubing for kinks and ensure the bag is below bladder level"},{"id":"C","text":"Notify the provider that the client is anuric"},{"id":"D","text":"Remove the catheter and reinsert a new one"}]',
    'B', 'Assess before intervening. A kinked tube or a bag hung above the bladder is the commonest and most easily fixed cause of an apparently dry catheter, and it takes seconds to rule out. Irrigating, reinserting or reporting anuria all act on a conclusion that has not been reached yet.'),

  ('nclex_rn', 'Basic Care and Comfort', 'Pain management', 'medium', 'multiple_choice',
    null,
    'A postoperative client rates pain as 8 out of 10 but is smiling and talking with visitors. What should the nurse do?',
    '[{"id":"A","text":"Reassess the pain rating, since the client does not appear to be in pain"},{"id":"B","text":"Administer the prescribed analgesic based on the client''s report"},{"id":"C","text":"Document that the client''s report is inconsistent with observed behaviour"},{"id":"D","text":"Offer a non-pharmacological measure instead"}]',
    'B', 'Pain is whatever the client says it is. Behaviour is an unreliable indicator -- people distract themselves, mask discomfort in front of visitors, and adapt to chronic pain -- so treating the report is correct. Each other option substitutes the nurse''s observation for the client''s report, which is the definition of undertreating pain.'),

  ('nclex_rn', 'Basic Care and Comfort', 'Sleep', 'hard', 'multiple_choice',
    null,
    'An older adult client reports difficulty sleeping in the hospital. Which nursing intervention should the nurse implement first?',
    '[{"id":"A","text":"Request a prescription for a sedative-hypnotic"},{"id":"B","text":"Cluster nursing care to reduce nighttime interruptions"},{"id":"C","text":"Encourage a daytime nap to make up the lost sleep"},{"id":"D","text":"Offer caffeinated tea in the evening for comfort"}]',
    'B', 'Non-pharmacological measures come first, and in a hospital the biggest single cause of broken sleep is being woken by staff. Sedative-hypnotics in older adults raise the risk of falls, delirium and next-day sedation; daytime napping reduces night-time sleep drive; and caffeine in the evening works against the goal.'),

  -- ============== Pharmacological and Parenteral Therapies ==============

  ('nclex_rn', 'Pharmacological and Parenteral Therapies', 'Anticoagulants', 'easy', 'multiple_choice',
    null,
    'A client receiving warfarin has an INR of 6.2. What should the nurse anticipate?',
    '[{"id":"A","text":"Increasing the warfarin dose"},{"id":"B","text":"Holding the warfarin and preparing to administer vitamin K"},{"id":"C","text":"Administering protamine sulfate"},{"id":"D","text":"No change, since this INR is therapeutic"}]',
    'B', 'Therapeutic INR for most indications is 2 to 3, so 6.2 is a serious bleeding risk. Warfarin is held and vitamin K is the reversal agent. Protamine sulfate reverses heparin, not warfarin -- pairing each anticoagulant with its own antidote is the point of the question.'),

  ('nclex_rn', 'Pharmacological and Parenteral Therapies', 'Digoxin', 'easy', 'multiple_choice',
    null,
    'Before administering digoxin, the nurse counts an apical pulse of 52 beats per minute in an adult client. What should the nurse do?',
    '[{"id":"A","text":"Administer the dose as scheduled"},{"id":"B","text":"Hold the dose and notify the provider"},{"id":"C","text":"Administer half the dose"},{"id":"D","text":"Recheck the radial pulse and administer if it is above 60"}]',
    'B', 'Digoxin slows conduction, so it is held in an adult when the apical rate is below 60 and the prescriber is notified. Splitting a dose is prescribing, and a radial pulse is less reliable than an apical one in a client who may have a pulse deficit -- checking the easier site to get the answer you want is the trap here.'),

  ('nclex_rn', 'Pharmacological and Parenteral Therapies', 'Insulin', 'medium', 'multiple_choice',
    null,
    'A client receives regular insulin at 0730. At what time should the nurse be most alert for hypoglycemia?',
    '[{"id":"A","text":"0745 to 0800"},{"id":"B","text":"0930 to 1130"},{"id":"C","text":"1400 to 1600"},{"id":"D","text":"1900 to 2100"}]',
    'B', 'Regular insulin peaks roughly 2 to 4 hours after a subcutaneous dose, which places the highest hypoglycemia risk from about 0930 to 1130. Fifteen minutes after the dose is barely past onset, and the later windows fall outside the peak for this insulin -- matching each insulin to its own peak is what makes the timing question answerable.'),

  ('nclex_rn', 'Pharmacological and Parenteral Therapies', 'Antibiotics', 'medium', 'multiple_choice',
    null,
    'A client receiving intravenous vancomycin develops flushing of the face and neck during infusion. What should the nurse do first?',
    '[{"id":"A","text":"Stop the infusion and prepare to administer epinephrine"},{"id":"B","text":"Slow the infusion rate and notify the provider"},{"id":"C","text":"Continue the infusion and document the finding"},{"id":"D","text":"Administer the remaining dose as a rapid bolus"}]',
    'B', 'Flushing during vancomycin infusion is an infusion-rate reaction caused by histamine release rather than a true allergy, and slowing the rate is the correct first response. Epinephrine is for anaphylaxis, which this is not; continuing unchanged lets it worsen; and a rapid bolus is exactly what causes it.'),

  ('nclex_rn', 'Pharmacological and Parenteral Therapies', 'Dosage calculation', 'medium', 'student_produced_response',
    null,
    'A provider prescribes 750 mg of an antibiotic. The pharmacy supplies a vial containing 250 mg per 5 mL. How many milliliters should the nurse administer?',
    null, '15', 'Set up the proportion 250 mg / 5 mL = 750 mg / x. Cross-multiplying gives 250x = 3750, so x = 15 mL. Checking the direction: the ordered dose is three times what is in 5 mL, so the volume must be three times 5 mL.'),

  ('nclex_rn', 'Pharmacological and Parenteral Therapies', 'Dosage calculation', 'hard', 'student_produced_response',
    null,
    'A client weighing 70 kg is prescribed a medication at 0.5 mg per kg per dose. The medication is supplied as 10 mg per mL. How many milliliters should the nurse administer per dose?',
    null, '3.5', 'The dose is 0.5 mg/kg times 70 kg, which is 35 mg. At 10 mg per mL, 35 mg is 3.5 mL. Dividing the weight by the concentration first is the usual error and gives an answer with no meaningful units.'),

  ('nclex_rn', 'Pharmacological and Parenteral Therapies', 'Opioids', 'medium', 'multiple_choice',
    null,
    'A client receiving intravenous morphine has a respiratory rate of 7 breaths per minute and is difficult to arouse. Which medication should the nurse anticipate administering?',
    '[{"id":"A","text":"Flumazenil"},{"id":"B","text":"Naloxone"},{"id":"C","text":"Acetylcysteine"},{"id":"D","text":"Protamine sulfate"}]',
    'B', 'Naloxone reverses opioid-induced respiratory depression. Flumazenil reverses benzodiazepines, acetylcysteine treats acetaminophen overdose, and protamine reverses heparin -- this question is really asking whether the antidote is matched to the drug class rather than to the symptom.'),

  ('nclex_rn', 'Pharmacological and Parenteral Therapies', 'Medication teaching', 'medium', 'multiple_response',
    null,
    'A client is starting an angiotensin-converting enzyme inhibitor. Which statements should the nurse include in teaching? Select all that apply.',
    '[{"id":"A","text":"A dry, persistent cough may develop and should be reported"},{"id":"B","text":"Rise slowly from sitting or lying to reduce dizziness"},{"id":"C","text":"Use a potassium-based salt substitute to reduce sodium intake"},{"id":"D","text":"Report any swelling of the face, lips, or tongue immediately"},{"id":"E","text":"Stop the medication as soon as blood pressure is normal"}]',
    'A,B,D', 'ACE inhibitors cause a dry cough through bradykinin accumulation, cause orthostatic hypotension particularly at the start, and can cause angioedema, which is an airway emergency. They also raise potassium, so potassium-based salt substitutes are contraindicated, and hypertension treatment is ongoing -- stopping when the number normalizes is why the number stops being normal.'),

  ('nclex_rn', 'Pharmacological and Parenteral Therapies', 'Intravenous therapy', 'hard', 'multiple_choice',
    null,
    'A nurse notices that the skin around a peripheral intravenous site is cool, pale, and swollen, and the infusion has slowed. What is the nurse''s first action?',
    '[{"id":"A","text":"Flush the catheter with saline to restore flow"},{"id":"B","text":"Stop the infusion and remove the catheter"},{"id":"C","text":"Apply warm compresses and continue the infusion"},{"id":"D","text":"Elevate the extremity and increase the infusion rate"}]',
    'B', 'Cool, pale, swollen tissue with a slowing infusion is infiltration: fluid is entering the tissue rather than the vein. The infusion stops and the catheter comes out before anything else. Flushing pushes more fluid into the tissue, and continuing or speeding the infusion makes the injury larger.'),

  -- ============== Reduction of Risk Potential ==============

  ('nclex_rn', 'Reduction of Risk Potential', 'Laboratory values', 'easy', 'multiple_choice',
    null,
    'Which laboratory result should the nurse report to the provider immediately for a client receiving heparin?',
    '[{"id":"A","text":"Platelet count of 68,000 per microliter"},{"id":"B","text":"Hemoglobin of 13.5 g/dL"},{"id":"C","text":"White blood cell count of 8,000 per microliter"},{"id":"D","text":"Sodium of 138 mEq/L"}]',
    'A', 'A falling platelet count in a client on heparin raises the possibility of heparin-induced thrombocytopenia, which paradoxically causes clotting rather than bleeding and requires the heparin to be stopped. The other three values are all within normal limits and would not be reported as abnormal at all.'),

  ('nclex_rn', 'Reduction of Risk Potential', 'Procedures', 'medium', 'multiple_choice',
    null,
    'A client is scheduled for a bronchoscopy. Which nursing action is essential after the procedure?',
    '[{"id":"A","text":"Offer fluids as soon as the client is awake"},{"id":"B","text":"Withhold food and fluids until the gag reflex returns"},{"id":"C","text":"Ambulate the client immediately to prevent atelectasis"},{"id":"D","text":"Position the client flat on the back"}]',
    'B', 'The topical anesthetic used for bronchoscopy suppresses the gag reflex, so anything swallowed before it returns can be aspirated. Fluids are withheld until the reflex is confirmed. Immediate ambulation is unnecessary, and lying flat after airway instrumentation works against airway protection.'),

  ('nclex_rn', 'Reduction of Risk Potential', 'Diagnostic tests', 'medium', 'multiple_choice',
    null,
    'A client is scheduled for a contrast-enhanced computed tomography scan. Which finding should the nurse report to the provider before the procedure?',
    '[{"id":"A","text":"A serum creatinine of 2.4 mg/dL"},{"id":"B","text":"A blood pressure of 128 over 76"},{"id":"C","text":"A reported allergy to latex"},{"id":"D","text":"A history of appendectomy"}]',
    'A', 'Iodinated contrast is nephrotoxic, and an elevated creatinine signals impaired kidney function that makes contrast-induced nephropathy far likelier. The blood pressure is normal, latex allergy matters for gloves and equipment rather than for contrast, and a past appendectomy has no bearing on the scan.'),

  ('nclex_rn', 'Reduction of Risk Potential', 'Complications', 'medium', 'multiple_choice',
    null,
    'A client who had abdominal surgery two days ago reports sudden shortness of breath and pleuritic chest pain. What should the nurse suspect?',
    '[{"id":"A","text":"Pulmonary embolism"},{"id":"B","text":"Wound dehiscence"},{"id":"C","text":"Paralytic ileus"},{"id":"D","text":"Urinary retention"}]',
    'A', 'Sudden dyspnea with pleuritic chest pain in a postoperative, relatively immobile client is pulmonary embolism until proved otherwise. Dehiscence presents as a wound separating, ileus as absent bowel sounds and distension, and retention as a distended bladder -- none of them produce this respiratory picture.'),

  ('nclex_rn', 'Reduction of Risk Potential', 'Monitoring', 'hard', 'multiple_choice',
    null,
    'A client has a chest tube connected to a water-seal drainage system. The nurse observes continuous vigorous bubbling in the water-seal chamber. What does this most likely indicate?',
    '[{"id":"A","text":"Normal functioning of the system"},{"id":"B","text":"An air leak in the system"},{"id":"C","text":"Complete lung re-expansion"},{"id":"D","text":"Obstruction of the chest tube"}]',
    'B', 'Intermittent bubbling in the water-seal chamber with respiration is expected; continuous vigorous bubbling means air is entering the system from somewhere it should not, and the nurse traces the tubing for a leak. Full re-expansion produces the opposite finding -- bubbling and tidaling stop -- and an obstruction produces no bubbling at all.'),

  ('nclex_rn', 'Reduction of Risk Potential', 'Laboratory values', 'hard', 'multiple_response',
    null,
    'A client has a serum sodium of 118 mEq/L. Which findings should the nurse expect to assess? Select all that apply.',
    '[{"id":"A","text":"Confusion"},{"id":"B","text":"Seizures"},{"id":"C","text":"Headache"},{"id":"D","text":"Intense thirst with dry mucous membranes"},{"id":"E","text":"Hyperreflexia with muscle cramping"}]',
    'A,B,C', 'Severe hyponatremia pulls water into cells, and the cells that matter are in the brain -- so the presentation is neurological: headache, confusion, and at this level seizures. Intense thirst with dry membranes is the picture of hypernatremia, the opposite disorder, and hyperreflexia with cramping points to calcium and magnesium problems rather than sodium.'),

  ('nclex_rn', 'Reduction of Risk Potential', 'Vital signs', 'easy', 'multiple_choice',
    null,
    'A client''s blood pressure drops from 128/78 to 88/52 one hour after starting a new antihypertensive. What should the nurse do first?',
    '[{"id":"A","text":"Recheck the blood pressure and assess the client for symptoms"},{"id":"B","text":"Administer the next scheduled dose as ordered"},{"id":"C","text":"Place the client in high Fowler position"},{"id":"D","text":"Document the reading and reassess in four hours"}]',
    'A', 'Confirm the finding and assess the client before acting on a single reading -- a mis-cuffed or mis-timed measurement is common, and what the client looks like decides how urgent this is. Giving the next dose acts on an unconfirmed number in the wrong direction, sitting the client up lowers the pressure further, and waiting four hours is too long if the reading is real.'),

  -- ============== Physiological Adaptation ==============

  ('nclex_rn', 'Physiological Adaptation', 'Fluid and electrolytes', 'easy', 'multiple_choice',
    null,
    'A client with heart failure has gained 2.5 kg in three days. What does this finding most likely indicate?',
    '[{"id":"A","text":"Improved nutritional intake"},{"id":"B","text":"Fluid retention"},{"id":"C","text":"Increased muscle mass"},{"id":"D","text":"Measurement error"}]',
    'B', 'A kilogram is roughly a litre of fluid, so 2.5 kg in three days is fluid, not tissue -- nobody builds two and a half kilograms of muscle or fat in seventy-two hours. Daily weights are the most sensitive routine measure of fluid status in heart failure for exactly this reason.'),

  ('nclex_rn', 'Physiological Adaptation', 'Respiratory', 'medium', 'multiple_choice',
    null,
    'A client with chronic obstructive pulmonary disease has an oxygen saturation of 90 percent on 2 litres per minute by nasal cannula. What should the nurse do?',
    '[{"id":"A","text":"Increase the oxygen to 6 litres per minute"},{"id":"B","text":"Continue the current oxygen and monitor the client"},{"id":"C","text":"Remove the oxygen entirely"},{"id":"D","text":"Place the client on a non-rebreather mask"}]',
    'B', 'A saturation of 88 to 92 percent is an acceptable target in COPD, so 90 percent on 2 litres is where this client should be. Pushing the saturation higher can worsen carbon dioxide retention; removing oxygen abandons a client who needs it; and a non-rebreather is a large escalation with no indication here.'),

  ('nclex_rn', 'Physiological Adaptation', 'Cardiac', 'medium', 'multiple_choice',
    null,
    'A client reports crushing substernal chest pain radiating to the left arm. After ensuring the client is safe, which action should the nurse take first?',
    '[{"id":"A","text":"Obtain a 12-lead electrocardiogram"},{"id":"B","text":"Draw cardiac biomarkers"},{"id":"C","text":"Administer a stool softener"},{"id":"D","text":"Schedule an echocardiogram"}]',
    'A', 'The electrocardiogram is the fastest test that changes management, because ST-segment elevation starts a reperfusion clock immediately. Biomarkers take time to rise and to result, an echocardiogram is not the first-line test for acute coronary syndrome, and a stool softener is a comfort measure with no bearing on the emergency.'),

  ('nclex_rn', 'Physiological Adaptation', 'Endocrine', 'medium', 'multiple_choice',
    null,
    'A client with type 1 diabetes has a blood glucose of 480 mg/dL, deep rapid respirations, and a fruity odor on the breath. What should the nurse anticipate?',
    '[{"id":"A","text":"Administering oral glucose"},{"id":"B","text":"Initiating intravenous fluids and an insulin infusion"},{"id":"C","text":"Withholding all fluids until glucose normalizes"},{"id":"D","text":"Administering a subcutaneous long-acting insulin dose only"}]',
    'B', 'This is diabetic ketoacidosis, and treatment is fluid resuscitation plus a regular insulin infusion -- volume depletion is usually the more immediately dangerous half. Oral glucose treats the opposite problem, withholding fluids worsens the dehydration driving the picture, and long-acting insulin alone acts far too slowly.'),

  ('nclex_rn', 'Physiological Adaptation', 'Neurological', 'hard', 'multiple_choice',
    null,
    'A client with a head injury has a blood pressure of 178/62, a pulse of 48, and irregular respirations. What does the nurse recognize about these findings?',
    '[{"id":"A","text":"They indicate hypovolemic shock"},{"id":"B","text":"They indicate increasing intracranial pressure and require immediate provider notification"},{"id":"C","text":"They are an expected response to pain"},{"id":"D","text":"They indicate an infection"}]',
    'B', 'Widening pulse pressure, bradycardia and irregular respirations are Cushing triad, a late and ominous sign of rising intracranial pressure. Hypovolemic shock produces the reverse -- low pressure and a fast pulse -- and neither pain nor infection produces bradycardia with hypertension.'),

  ('nclex_rn', 'Physiological Adaptation', 'Renal', 'hard', 'multiple_choice',
    null,
    'A client with chronic kidney disease has a potassium of 6.4 mEq/L. Which intervention should the nurse anticipate first?',
    '[{"id":"A","text":"Administering intravenous calcium gluconate"},{"id":"B","text":"Encouraging a high-potassium diet"},{"id":"C","text":"Administering intravenous potassium chloride"},{"id":"D","text":"Withholding all intravenous fluids"}]',
    'A', 'Calcium gluconate does not lower potassium; it stabilizes the cardiac membrane against the arrhythmia that is the immediate threat, which is why it comes first while the potassium-lowering measures are prepared. Giving potassium or encouraging it in the diet worsens the problem, and withholding fluids does not address it.'),

  ('nclex_rn', 'Physiological Adaptation', 'Shock', 'hard', 'multiple_choice',
    null,
    'A client is admitted with a temperature of 39.2 degrees Celsius, a heart rate of 122, a blood pressure of 84/48, and a lactate of 4.2 mmol/L. What does the nurse recognize?',
    '[{"id":"A","text":"Cardiogenic shock"},{"id":"B","text":"Septic shock"},{"id":"C","text":"Neurogenic shock"},{"id":"D","text":"Anaphylactic shock"}]',
    'B', 'Fever, tachycardia, hypotension and a raised lactate together are septic shock -- the lactate is the marker of tissue hypoperfusion that separates sepsis from an ordinary febrile illness. Cardiogenic shock follows pump failure rather than infection, neurogenic shock presents with bradycardia rather than tachycardia, and anaphylaxis follows an exposure and brings airway and skin findings.'),

  ('nclex_rn', 'Physiological Adaptation', 'Fluid and electrolytes', 'medium', 'multiple_choice',
    null,
    'A client receiving intravenous fluids develops crackles in the lung bases, jugular venous distension, and a bounding pulse. What should the nurse do first?',
    '[{"id":"A","text":"Increase the infusion rate to improve perfusion"},{"id":"B","text":"Slow or stop the infusion and elevate the head of the bed"},{"id":"C","text":"Place the client flat to improve venous return"},{"id":"D","text":"Administer an additional fluid bolus"}]',
    'B', 'Crackles, jugular venous distension and a bounding pulse are fluid volume overload, so the first action is to stop adding fluid and to sit the client up to ease the work of breathing. Every other option adds volume or worsens the pulmonary congestion.')

) as v(section, domain, skill, difficulty, question_type, stimulus, question_text, answer_choices, correct_answer, explanation)
where e.slug = 'nclex-rn'
on conflict (exam_id, md5(coalesce(stimulus, '') || E'\x1f' || question_text)) do nothing;

-- Available only now that there is a bank behind the card.
update public.exam_definitions
set status = 'available'
where slug = 'nclex-rn'
  and exists (
    select 1 from public.diagnostic_questions q
    where q.exam_id = exam_definitions.id and q.status = 'published'
  );


-- ======================================================================
-- FILE: 20260906_05_mcat_question_bank.sql
-- ======================================================================

-- An original MCAT-style question bank.
--
-- Every passage and every item was written for this migration. None of it
-- reproduces, paraphrases or is derived from an AAMC item. What is taken
-- from the AAMC is the published content outline: the four sections, the
-- foundational concepts they examine, and the fact that most of the exam is
-- passage-based rather than discrete.
--
-- That last part is the design constraint here, and the brief for this work
-- said it in as many words: do not turn the MCAT into isolated trivia. So
-- most items below carry a passage -- an experiment with a result to
-- interpret, a table to read, an argument to evaluate -- and the question
-- asks the student to do something with it rather than to recall a fact
-- that happens to be nearby.
--
-- Passages are stored on each item rather than in a table of their own,
-- which looks like duplication and is deliberate: the bank picker selects
-- items independently, so two questions from one passage will usually not
-- appear together, and an item that cannot be answered without a sibling it
-- may never be shown alongside is a broken item. Each one here stands alone
-- with its passage.
--
-- CARS items carry no science at all, by design. The section tests reading,
-- and a CARS item that rewards outside knowledge is testing the wrong thing.
--
-- Idempotent through the (exam_id, stimulus + question_text) unique index.

insert into public.diagnostic_questions
  (exam_id, section, domain, skill, difficulty, question_type, stimulus, question_text, answer_choices, correct_answer, explanation, status, source_type, reviewed_at)
select e.id, v.section, v.domain, v.skill, v.difficulty, v.question_type, v.stimulus, v.question_text, v.answer_choices::jsonb, v.correct_answer, v.explanation, 'published', 'human_authored', now()
from public.exam_definitions e
cross join (values

  -- ============== Chemical and Physical Foundations ==============

  ('chem_phys', 'Thermodynamics and kinetics', 'Reaction energetics', 'medium', 'multiple_choice',
    'Researchers measured the rate of an enzyme-catalysed reaction at several temperatures. Rate rose steadily from 20 to 40 degrees Celsius, peaked near 42 degrees, then fell sharply, reaching almost zero by 60 degrees. A parallel run with the same reactants and no enzyme showed rate rising steadily across the entire range.',
    'Which explanation best accounts for the difference between the two runs above 45 degrees Celsius?',
    '[{"id":"A","text":"The uncatalysed reaction has a lower activation energy at high temperature"},{"id":"B","text":"The enzyme denatures, removing the catalysed pathway, while the uncatalysed reaction continues to speed up"},{"id":"C","text":"The reactants are consumed faster in the catalysed run"},{"id":"D","text":"The equilibrium constant of the catalysed reaction decreases with temperature"}]',
    'B', 'Rate rises with temperature for any reaction because more collisions clear the activation barrier. An enzyme adds a lower-barrier pathway, but it is a protein and loses its tertiary structure above its optimum, which removes that pathway entirely. Choice A inverts the definition of a catalyst; choice C would affect both runs; and a change in equilibrium constant describes where the reaction ends up, not how fast it gets there.'),

  ('chem_phys', 'Thermodynamics and kinetics', 'Catalysis', 'medium', 'multiple_choice',
    'Researchers measured the rate of an enzyme-catalysed reaction at several temperatures. Rate rose steadily from 20 to 40 degrees Celsius, peaked near 42 degrees, then fell sharply, reaching almost zero by 60 degrees. A parallel run with the same reactants and no enzyme showed rate rising steadily across the entire range.',
    'Compared with the uncatalysed reaction at 30 degrees Celsius, the catalysed reaction has:',
    '[{"id":"A","text":"a lower activation energy and the same overall free energy change"},{"id":"B","text":"a lower activation energy and a more negative free energy change"},{"id":"C","text":"the same activation energy and a more negative free energy change"},{"id":"D","text":"a higher activation energy and the same free energy change"}]',
    'A', 'A catalyst lowers the activation barrier and is unchanged at the end, so it alters the path and not the endpoints. The free energy change is a state function fixed by the reactants and products, which is why a catalyst can never make an unfavourable reaction favourable -- only faster.'),

  ('chem_phys', 'Acids and bases', 'Buffers', 'medium', 'multiple_choice',
    'A buffer is prepared containing 0.10 M of a weak acid HA and 0.10 M of its conjugate base A-. The acid has a pKa of 4.8. A small volume of strong base is then added.',
    'What happens to the pH of the solution immediately after the strong base is added?',
    '[{"id":"A","text":"It falls sharply, because the base consumes A-"},{"id":"B","text":"It rises slightly, because HA neutralises most of the added base"},{"id":"C","text":"It rises sharply, because the buffer has no capacity at equal concentrations"},{"id":"D","text":"It does not change at all, because buffers hold pH exactly constant"}]',
    'B', 'Added strong base is consumed by the weak acid HA, converting some of it to A-. That shifts the ratio of base to acid slightly upward, so the pH rises slightly rather than sharply. Buffer capacity is at its maximum when the two are equal, which is the opposite of choice C, and no buffer holds pH exactly constant -- it resists change rather than preventing it.'),

  ('chem_phys', 'Acids and bases', 'pH calculation', 'hard', 'multiple_choice',
    'A buffer is prepared containing 0.10 M of a weak acid HA and 0.10 M of its conjugate base A-. The acid has a pKa of 4.8.',
    'What is the pH of the buffer before any base is added?',
    '[{"id":"A","text":"1.0"},{"id":"B","text":"4.8"},{"id":"C","text":"7.0"},{"id":"D","text":"9.2"}]',
    'B', 'The Henderson-Hasselbalch equation gives pH = pKa + log([A-]/[HA]). With equal concentrations the ratio is 1, its logarithm is 0, and the pH equals the pKa exactly. This is the single most useful fact about buffers: at the half-equivalence point, pH and pKa are the same number.'),

  ('chem_phys', 'Fluids and circulation', 'Flow', 'hard', 'multiple_choice',
    'A rigid tube carries an incompressible fluid at steady flow. Partway along its length the tube narrows to half its original radius before widening again.',
    'In the narrowed region, compared with the wide region, the fluid has:',
    '[{"id":"A","text":"a higher speed and a lower pressure"},{"id":"B","text":"a higher speed and a higher pressure"},{"id":"C","text":"a lower speed and a lower pressure"},{"id":"D","text":"a lower speed and a higher pressure"}]',
    'A', 'Continuity requires that the same volume pass every cross-section per second, so halving the radius quarters the area and quadruples the speed. Bernoulli then requires that the faster region be at lower pressure, since the total energy per unit volume is conserved. The intuition that a squeeze raises pressure is the trap, and it is the reason this appears on every version of this exam.'),

  ('chem_phys', 'Electrochemistry', 'Redox', 'medium', 'multiple_choice',
    'In an electrochemical cell, zinc metal is oxidised at one electrode and copper ions are reduced at the other, producing a measurable voltage.',
    'At which electrode does oxidation occur, and what happens to the mass of that electrode over time?',
    '[{"id":"A","text":"The cathode; its mass increases"},{"id":"B","text":"The cathode; its mass decreases"},{"id":"C","text":"The anode; its mass increases"},{"id":"D","text":"The anode; its mass decreases"}]',
    'D', 'Oxidation always occurs at the anode -- the two words share a vowel, which is the standard mnemonic. Zinc atoms lose electrons and leave the electrode as ions in solution, so the zinc electrode loses mass while the copper cathode gains it as copper ions plate out.'),

  ('chem_phys', 'Atomic structure', 'Periodic trends', 'easy', 'multiple_choice',
    null,
    'Which of the following correctly describes the trend in first ionisation energy across a period from left to right?',
    '[{"id":"A","text":"It decreases, because atomic radius increases"},{"id":"B","text":"It increases, because effective nuclear charge increases"},{"id":"C","text":"It stays constant, because the number of shells does not change"},{"id":"D","text":"It decreases, because electron shielding increases"}]',
    'B', 'Across a period, protons are added to the nucleus while electrons enter the same shell, so shielding barely changes and the effective nuclear charge felt by an outer electron rises. The atom holds its electrons more tightly, so more energy is needed to remove one. Radius decreases across a period, which is the opposite of what choice A assumes.'),

  -- ============== Biological and Biochemical Foundations ==============

  ('bio_biochem', 'Enzymes', 'Inhibition', 'hard', 'multiple_choice',
    'An enzyme was assayed at a range of substrate concentrations, with and without an added compound X. Without X, the apparent Km was 4 micromolar and Vmax was 100 units. With X present, the apparent Km rose to 12 micromolar while Vmax remained 100 units.',
    'What type of inhibition does compound X most likely exhibit?',
    '[{"id":"A","text":"Competitive"},{"id":"B","text":"Noncompetitive"},{"id":"C","text":"Uncompetitive"},{"id":"D","text":"Irreversible"}]',
    'A', 'A competitive inhibitor binds the active site and can be outcompeted by enough substrate, so Vmax is unchanged while the substrate concentration needed to reach half of it rises -- exactly the pattern here. Noncompetitive inhibition lowers Vmax with Km unchanged, uncompetitive lowers both, and irreversible inhibition lowers Vmax by permanently removing enzyme.'),

  ('bio_biochem', 'Enzymes', 'Kinetics', 'medium', 'multiple_choice',
    'An enzyme was assayed at a range of substrate concentrations, with and without an added compound X. Without X, the apparent Km was 4 micromolar and Vmax was 100 units. With X present, the apparent Km rose to 12 micromolar while Vmax remained 100 units.',
    'Which experimental change would most directly test the proposed mechanism of compound X?',
    '[{"id":"A","text":"Repeating the assay at a much higher substrate concentration"},{"id":"B","text":"Repeating the assay at a lower enzyme concentration"},{"id":"C","text":"Measuring the molecular weight of compound X"},{"id":"D","text":"Repeating the assay at a lower temperature"}]',
    'A', 'The claim is that X competes for the active site, and the definitive prediction of that claim is that enough substrate should outcompete it and restore the uninhibited rate. Lowering enzyme concentration scales everything down without discriminating between mechanisms, and neither molecular weight nor temperature tests where X binds.'),

  ('bio_biochem', 'Metabolism', 'Cellular respiration', 'medium', 'multiple_choice',
    'A cell culture is treated with a compound that makes the inner mitochondrial membrane freely permeable to protons. Oxygen consumption rises, but ATP production falls sharply.',
    'Which explanation best accounts for this result?',
    '[{"id":"A","text":"The electron transport chain is inhibited, so less oxygen is used"},{"id":"B","text":"The proton gradient is dissipated, so ATP synthase cannot use it, while electron transport runs unopposed"},{"id":"C","text":"Glycolysis is inhibited, so no substrate reaches the mitochondrion"},{"id":"D","text":"ATP synthase is running in reverse, hydrolysing ATP to pump protons"}]',
    'B', 'This is an uncoupler. Electron transport builds a proton gradient and ATP synthase spends it; making the membrane leaky removes the gradient, so ATP synthesis fails while the chain runs faster than ever with nothing backing it up -- which is why oxygen consumption rises. Choice A contradicts the rise in oxygen use, and the energy released appears as heat.'),

  ('bio_biochem', 'Molecular biology', 'Gene expression', 'medium', 'multiple_choice',
    'A bacterial operon encoding enzymes for lactose metabolism is transcribed only when lactose is present and glucose is absent.',
    'Which mechanism best explains why the operon is silent when both sugars are present?',
    '[{"id":"A","text":"The repressor remains bound to the operator"},{"id":"B","text":"Catabolite repression keeps cyclic AMP low, so the activator does not bind"},{"id":"C","text":"The structural genes are deleted in the presence of glucose"},{"id":"D","text":"Ribosomes cannot translate the mRNA when glucose is present"}]',
    'B', 'Lactose releases the repressor, so the operator is free -- but transcription still needs the cAMP-bound activator, and glucose keeps cAMP low. The system is a logical AND, and glucose fails the second condition rather than the first, which is what makes choice A the tempting wrong answer.'),

  ('bio_biochem', 'Cell biology', 'Membrane transport', 'easy', 'multiple_choice',
    null,
    'A cell is placed in a solution with a lower solute concentration than its cytoplasm. What happens?',
    '[{"id":"A","text":"Water leaves the cell and it shrinks"},{"id":"B","text":"Water enters the cell and it swells"},{"id":"C","text":"Solute enters the cell down its gradient until concentrations equalise"},{"id":"D","text":"Nothing, because the membrane is impermeable to water"}]',
    'B', 'Water moves toward the higher solute concentration, which here is inside, so the cell takes up water and swells -- the solution is hypotonic to the cell. Choice C describes what would happen if the membrane were freely permeable to the solute, which is usually the point of the question, and aquaporins make choice D false for essentially every cell.'),

  ('bio_biochem', 'Genetics', 'Inheritance', 'hard', 'multiple_choice',
    'A recessive condition appears in a child whose parents are both unaffected. Neither set of grandparents was affected.',
    'What is the probability that a second child of the same parents will be affected?',
    '[{"id":"A","text":"0"},{"id":"B","text":"1 in 4"},{"id":"C","text":"1 in 2"},{"id":"D","text":"3 in 4"}]',
    'B', 'An affected child of two unaffected parents means both parents are carriers, so the cross is Aa by Aa and one quarter of offspring are affected. Each conception is independent, so having had one affected child does not change the odds for the next -- the belief that it does is the commonest error on pedigree questions.'),

  -- ============== Psychological, Social, and Biological Foundations ==============

  ('psych_soc', 'Learning and memory', 'Conditioning', 'medium', 'multiple_choice',
    'In a study, participants heard a tone immediately before receiving a mild puff of air to the eye. After many pairings, participants blinked when the tone was played alone.',
    'In this experiment, the tone is best described as:',
    '[{"id":"A","text":"an unconditioned stimulus"},{"id":"B","text":"a conditioned stimulus"},{"id":"C","text":"an unconditioned response"},{"id":"D","text":"a negative reinforcer"}]',
    'B', 'The air puff produces a blink without any learning, which makes it the unconditioned stimulus. The tone started neutral and acquired its power through pairing, which is the definition of a conditioned stimulus. Reinforcement belongs to operant conditioning, where behaviour is emitted rather than elicited.'),

  ('psych_soc', 'Learning and memory', 'Extinction', 'hard', 'multiple_choice',
    'In a study, participants heard a tone immediately before receiving a mild puff of air to the eye. After many pairings, participants blinked when the tone was played alone. The tone was then presented alone repeatedly, and blinking gradually stopped. After a day away, the tone was presented again and weak blinking returned.',
    'The return of blinking after the delay is best described as:',
    '[{"id":"A","text":"spontaneous recovery"},{"id":"B","text":"stimulus generalisation"},{"id":"C","text":"second-order conditioning"},{"id":"D","text":"habituation"}]',
    'A', 'Extinction suppresses a conditioned response rather than erasing the association, and the response can reappear after a rest interval -- that reappearance is spontaneous recovery. Generalisation is responding to a similar but different stimulus, second-order conditioning builds a new association on an existing one, and habituation is a decline in response to a repeated harmless stimulus with no pairing involved.'),

  ('psych_soc', 'Social psychology', 'Attribution', 'medium', 'multiple_choice',
    'A driver is cut off in traffic and immediately concludes that the other driver is reckless and inconsiderate. Later the same day, the driver cuts someone off while rushing to a hospital, and attributes it to the emergency.',
    'This pattern is best described as:',
    '[{"id":"A","text":"the fundamental attribution error, applied asymmetrically to self and other"},{"id":"B","text":"cognitive dissonance"},{"id":"C","text":"the just-world hypothesis"},{"id":"D","text":"groupthink"}]',
    'A', 'Explaining someone else''s behaviour by their character while explaining one''s own by the situation is the actor-observer asymmetry of the fundamental attribution error. Dissonance is the discomfort of holding conflicting beliefs, the just-world hypothesis is the belief that people get what they deserve, and groupthink is a failure of group decision-making.'),

  ('psych_soc', 'Biological bases of behaviour', 'Neurotransmission', 'medium', 'multiple_choice',
    'A drug blocks the reuptake transporter for a particular neurotransmitter at the synapse.',
    'What is the most direct consequence of this action?',
    '[{"id":"A","text":"Less neurotransmitter is released into the synapse"},{"id":"B","text":"The neurotransmitter remains in the synaptic cleft longer"},{"id":"C","text":"Postsynaptic receptors are destroyed"},{"id":"D","text":"The action potential travels faster along the axon"}]',
    'B', 'Reuptake is how a released transmitter is cleared from the cleft, so blocking it leaves the transmitter available to bind receptors for longer and prolongs the signal. Release is presynaptic and unaffected, receptors are not destroyed, and axonal conduction speed depends on myelination and diameter rather than on synaptic clearance.'),

  ('psych_soc', 'Sociology', 'Research methods', 'hard', 'multiple_choice',
    'A survey finds that neighbourhoods with more parks report better self-rated health. The researchers conclude that building parks improves health.',
    'Which is the strongest objection to that conclusion?',
    '[{"id":"A","text":"The sample size was too small to detect an effect"},{"id":"B","text":"Wealthier neighbourhoods may have both more parks and better health for other reasons"},{"id":"C","text":"Self-rated health is not a valid construct"},{"id":"D","text":"Parks are not the only kind of green space"}]',
    'B', 'The study is observational, so the association could be produced entirely by a third variable that causes both -- income being the obvious candidate. That is confounding, and it is the objection that undermines the causal claim rather than merely qualifying it. Sample size affects precision, not causal direction, and the other two narrow the finding without challenging its logic.'),

  ('psych_soc', 'Sensation and perception', 'Thresholds', 'easy', 'multiple_choice',
    null,
    'The smallest difference between two stimuli that a person can reliably detect is called the:',
    '[{"id":"A","text":"absolute threshold"},{"id":"B","text":"just-noticeable difference"},{"id":"C","text":"sensory adaptation point"},{"id":"D","text":"signal detection criterion"}]',
    'B', 'The just-noticeable difference is the smallest detectable change between two stimuli, while the absolute threshold is the smallest detectable stimulus in the first place. Sensory adaptation is a decline in response to a constant stimulus, and the detection criterion is how willing an observer is to say they noticed something.'),

  -- ============== Critical Analysis and Reasoning Skills ==============
  -- No science in these, by design. The section tests reading, and an item
  -- that rewards outside knowledge is testing the wrong thing.

  ('cars', 'Foundations of comprehension', 'Main idea', 'medium', 'multiple_choice',
    'Restoration is usually described as returning a building to how it looked at some earlier moment. But every building has had many moments, and choosing one is an argument rather than a discovery. The restorer who strips a Victorian church back to its medieval fabric has not uncovered the true building; they have decided that six centuries of use were an interruption. That decision may be defensible. What it is not is neutral, and the language of restoration -- returning, uncovering, revealing -- works hard to make it sound as though no decision was made at all.',
    'The main idea of the passage is that restoration:',
    '[{"id":"A","text":"should generally be avoided in favour of preservation"},{"id":"B","text":"involves a choice that its own vocabulary tends to conceal"},{"id":"C","text":"is impossible to carry out accurately on medieval buildings"},{"id":"D","text":"has improved as techniques have become more precise"}]',
    'B', 'The passage argues that picking which moment to restore to is an argument, and that words like "uncovering" disguise it as a discovery. It explicitly allows that the decision "may be defensible", so it is not arguing against restoration -- which rules out A -- and it makes no claim about accuracy or about improvement over time.'),

  ('cars', 'Reasoning within the text', 'Author attitude', 'hard', 'multiple_choice',
    'Restoration is usually described as returning a building to how it looked at some earlier moment. But every building has had many moments, and choosing one is an argument rather than a discovery. The restorer who strips a Victorian church back to its medieval fabric has not uncovered the true building; they have decided that six centuries of use were an interruption. That decision may be defensible. What it is not is neutral, and the language of restoration -- returning, uncovering, revealing -- works hard to make it sound as though no decision was made at all.',
    'The author''s attitude towards restorers is best described as:',
    '[{"id":"A","text":"dismissive of their expertise"},{"id":"B","text":"critical of the vocabulary they work within rather than of their competence"},{"id":"C","text":"admiring of their commitment to historical accuracy"},{"id":"D","text":"indifferent to the outcomes of their work"}]',
    'B', 'The sentence "That decision may be defensible" concedes the work can be right, and the complaint is aimed squarely at the language, which "works hard" to hide a choice. Nothing questions the restorers'' skill, nothing admires them, and an indifferent author does not write the final sentence.'),

  ('cars', 'Reasoning beyond the text', 'Application', 'hard', 'multiple_choice',
    'Restoration is usually described as returning a building to how it looked at some earlier moment. But every building has had many moments, and choosing one is an argument rather than a discovery. The restorer who strips a Victorian church back to its medieval fabric has not uncovered the true building; they have decided that six centuries of use were an interruption. That decision may be defensible. What it is not is neutral, and the language of restoration -- returning, uncovering, revealing -- works hard to make it sound as though no decision was made at all.',
    'Which situation is most analogous to the author''s central concern?',
    '[{"id":"A","text":"A museum labelling a reconstructed vase as an original"},{"id":"B","text":"An editor calling a heavily rewritten manuscript the author''s definitive text"},{"id":"C","text":"A conservationist removing an invasive species from a wetland"},{"id":"D","text":"A translator producing two versions of a poem for different audiences"}]',
    'B', 'The concern is that a word implies a single true version was recovered when in fact one was chosen from many. "Definitive" does exactly that work for a manuscript with many states. The vase case is straightforward misrepresentation rather than a concealed choice; the wetland has an uncontested baseline; and the translator with two versions is being openly plural, which is the opposite of the complaint.'),

  ('cars', 'Foundations of comprehension', 'Inference', 'medium', 'multiple_choice',
    'For most of its history the word "amateur" carried no insult. It named someone who did a thing for love of it, and it was used approvingly of the naturalists, astronomers and archaeologists who did much of the observing that professionals later systematised. The shift came with the professions themselves, which needed a word for everyone outside them, and found one ready to hand. What changed was not the amateurs. It was who got to define competence.',
    'The passage suggests that the word "amateur" acquired its negative sense primarily because:',
    '[{"id":"A","text":"amateurs began producing lower-quality work"},{"id":"B","text":"professional groups needed a term for those outside them"},{"id":"C","text":"the activities themselves became more technically demanding"},{"id":"D","text":"the word was mistranslated from its original language"}]',
    'B', 'The passage says the shift came with the professions, which "needed a word for everyone outside them", and then states directly that what changed was not the amateurs. Choices A and C both locate the change in the amateurs or the work, which the final two sentences rule out.'),

  ('cars', 'Reasoning within the text', 'Argument structure', 'medium', 'multiple_choice',
    'For most of its history the word "amateur" carried no insult. It named someone who did a thing for love of it, and it was used approvingly of the naturalists, astronomers and archaeologists who did much of the observing that professionals later systematised. The shift came with the professions themselves, which needed a word for everyone outside them, and found one ready to hand. What changed was not the amateurs. It was who got to define competence.',
    'The examples of naturalists, astronomers and archaeologists function primarily to:',
    '[{"id":"A","text":"establish that the word once described people doing serious work"},{"id":"B","text":"argue that these three fields were unusually welcoming to outsiders"},{"id":"C","text":"contrast scientific amateurs with artistic ones"},{"id":"D","text":"show that professional standards were low at the time"}]',
    'A', 'The list supports the claim in the first sentence by naming amateurs whose work professionals later built on, which is what makes the later insult worth remarking on. It draws no contrast between fields, mentions no artistic amateurs, and says nothing about professional standards.')

) as v(section, domain, skill, difficulty, question_type, stimulus, question_text, answer_choices, correct_answer, explanation)
where e.slug = 'mcat'
on conflict (exam_id, md5(coalesce(stimulus, '') || E'\x1f' || question_text)) do nothing;

update public.exam_definitions
set status = 'available'
where slug = 'mcat'
  and exists (
    select 1 from public.diagnostic_questions q
    where q.exam_id = exam_definitions.id and q.status = 'published'
  );


-- ======================================================================
-- FILE: 20260906_06_gre_question_bank.sql
-- ======================================================================

-- An original GRE-style question bank.
--
-- Every item was written for this migration. None of it reproduces,
-- paraphrases or is derived from an ETS item. What is taken from ETS is the
-- published structure of the shortened General Test: two Verbal Reasoning
-- measures and two Quantitative, each scored 130 to 170, with the second
-- section of each measure pitched to how the first went.
--
-- That section-level adaptivity is why the GRE blueprint declares two
-- modules per section while the ACT and MCAT declare one: the engine's
-- existing two-module routing is the right shape for it. AceDecks routes on
-- its own transparent accuracy threshold and does not reproduce ETS's.
--
-- Verbal here is text completion, sentence equivalence and reading
-- comprehension. Sentence equivalence on the real exam asks for TWO answers
-- that produce the same meaning, which is stored as a multiple_response item
-- and graded all-or-nothing, exactly as ETS scores it.
--
-- The Analytical Writing measure is deliberately absent. It is a written
-- task, and faking it as a multiple-choice item would teach the wrong thing.
--
-- Idempotent through the (exam_id, stimulus + question_text) unique index.

insert into public.diagnostic_questions
  (exam_id, section, domain, skill, difficulty, question_type, stimulus, question_text, answer_choices, correct_answer, explanation, status, source_type, reviewed_at)
select e.id, v.section, v.domain, v.skill, v.difficulty, v.question_type, v.stimulus, v.question_text, v.answer_choices::jsonb, v.correct_answer, v.explanation, 'published', 'human_authored', now()
from public.exam_definitions e
cross join (values

  -- ============== Verbal Reasoning ==============

  ('verbal', 'Text completion', 'Single blank', 'easy', 'multiple_choice',
    'Although the committee had been assembled to resolve the dispute, its members proved so ______ that they could not agree even on an agenda.',
    'Select the word that best completes the text.',
    '[{"id":"A","text":"conciliatory"},{"id":"B","text":"fractious"},{"id":"C","text":"punctual"},{"id":"D","text":"resourceful"},{"id":"E","text":"deferential"}]',
    'B', 'The word "Although" sets up a contrast: the committee was meant to resolve a dispute but could not agree on anything. "Fractious" means quarrelsome, which supplies the contrast. "Conciliatory" and "deferential" both describe people who agree easily, which removes the contrast entirely, and punctuality and resourcefulness have no bearing on agreement.'),

  ('verbal', 'Text completion', 'Single blank', 'medium', 'multiple_choice',
    'Far from being the ______ figure of legend, the explorer emerges from these letters as anxious, indecisive, and frequently homesick.',
    'Select the word that best completes the text.',
    '[{"id":"A","text":"intrepid"},{"id":"B","text":"obscure"},{"id":"C","text":"prolific"},{"id":"D","text":"reticent"},{"id":"E","text":"itinerant"}]',
    'A', '"Far from being" signals that the blank is the opposite of what follows, and what follows is anxious and indecisive. "Intrepid" means fearless, which is the opposite required. "Obscure" and "reticent" are closer to the letters than against them, and neither "prolific" nor "itinerant" contrasts with anxiety.'),

  ('verbal', 'Text completion', 'Two blanks', 'hard', 'multiple_choice',
    'The author''s prose is often called difficult, but the difficulty is (i) ______ rather than accidental: every ambiguity is placed, and the reader who slows down finds the sentence (ii) ______ its own instructions for being read.',
    'Which pair best completes the text? Select one pair.',
    '[{"id":"A","text":"(i) deliberate  (ii) containing"},{"id":"B","text":"(i) unfortunate  (ii) concealing"},{"id":"C","text":"(i) deliberate  (ii) resisting"},{"id":"D","text":"(i) inevitable  (ii) refusing"},{"id":"E","text":"(i) trivial  (ii) containing"}]',
    'A', 'The first blank is opposed to "accidental" and supported by "every ambiguity is placed", so it must mean intended. The second is what the slow reader finds, and the sentence rewards them, so it must be positive. Choice C has the first blank right and the second backwards, which is exactly how a two-blank item is usually missed -- both halves have to work.'),

  ('verbal', 'Sentence equivalence', 'Equivalent completions', 'medium', 'multiple_response',
    'The new policy was praised as bold and denounced as reckless, which suggests that its authors had at least succeeded in being ______.',
    'Select the TWO answer choices that best complete the text and produce sentences alike in meaning.',
    '[{"id":"A","text":"decisive"},{"id":"B","text":"forthright"},{"id":"C","text":"cautious"},{"id":"D","text":"resolute"},{"id":"E","text":"ambiguous"},{"id":"F","text":"popular"}]',
    'A,D', 'A policy called both bold and reckless is at least not timid, so the blank needs a word for acting without hesitation. "Decisive" and "resolute" are near-synonyms and produce sentences alike in meaning, which is what this item type requires. "Forthright" is about candour rather than decisiveness, "cautious" contradicts both descriptions, and neither "ambiguous" nor "popular" has a partner here.'),

  ('verbal', 'Sentence equivalence', 'Equivalent completions', 'hard', 'multiple_response',
    'Reviewers who had expected a polemic were surprised by the book''s ______ tone, which weighs the opposing case more carefully than its own.',
    'Select the TWO answer choices that best complete the text and produce sentences alike in meaning.',
    '[{"id":"A","text":"strident"},{"id":"B","text":"measured"},{"id":"C","text":"temperate"},{"id":"D","text":"derivative"},{"id":"E","text":"cursory"},{"id":"F","text":"impassioned"}]',
    'B,C', 'The tone is surprising to readers expecting a polemic and it weighs the other side carefully, so it must be restrained. "Measured" and "temperate" are near-synonyms that both produce that sentence. "Strident" and "impassioned" are what a polemic sounds like, and "derivative" and "cursory" describe quality and thoroughness rather than tone -- and neither has a partner.'),

  ('verbal', 'Reading comprehension', 'Main idea', 'medium', 'multiple_choice',
    'The standard account holds that the printing press caused the rapid spread of literacy. The sequence, though, runs the other way at least as often. Presses were expensive, and printers set up where a reading public already existed to buy what they printed. In towns with established schools and a merchant class that needed contracts read, presses arrived early and multiplied; in towns without, presses arrived late and frequently failed. The press did not create its market so much as follow it -- and then, having followed it, enlarge it.',
    'The primary purpose of the passage is to:',
    '[{"id":"A","text":"argue that the printing press had little effect on literacy"},{"id":"B","text":"complicate a standard causal account without wholly rejecting it"},{"id":"C","text":"compare literacy rates in towns with and without schools"},{"id":"D","text":"explain why early printers frequently went out of business"},{"id":"E","text":"describe the economics of press ownership in detail"}]',
    'B', 'The passage says the causation runs "the other way at least as often" -- not always -- and the final clause concedes that the press did enlarge its market once established. That is a complication rather than a rejection, which rules out A. The town comparison and the failed printers are evidence for the argument rather than the point of it.'),

  ('verbal', 'Reading comprehension', 'Inference', 'hard', 'multiple_choice',
    'The standard account holds that the printing press caused the rapid spread of literacy. The sequence, though, runs the other way at least as often. Presses were expensive, and printers set up where a reading public already existed to buy what they printed. In towns with established schools and a merchant class that needed contracts read, presses arrived early and multiplied; in towns without, presses arrived late and frequently failed. The press did not create its market so much as follow it -- and then, having followed it, enlarge it.',
    'The passage suggests that a town with a press that failed quickly most likely:',
    '[{"id":"A","text":"had unusually high printing costs"},{"id":"B","text":"lacked an established reading public when the press arrived"},{"id":"C","text":"had banned printed material"},{"id":"D","text":"was located far from major trade routes"},{"id":"E","text":"had more presses than it could support"}]',
    'B', 'The passage pairs late arrival and frequent failure with towns lacking schools and a merchant class -- that is, lacking readers. Cost is described as uniformly high rather than variable by town, and bans, trade routes and oversupply are never mentioned.'),

  ('verbal', 'Reading comprehension', 'Function of a detail', 'medium', 'multiple_choice',
    'The standard account holds that the printing press caused the rapid spread of literacy. The sequence, though, runs the other way at least as often. Presses were expensive, and printers set up where a reading public already existed to buy what they printed. In towns with established schools and a merchant class that needed contracts read, presses arrived early and multiplied; in towns without, presses arrived late and frequently failed. The press did not create its market so much as follow it -- and then, having followed it, enlarge it.',
    'The mention that presses were expensive serves primarily to:',
    '[{"id":"A","text":"explain why printers needed an existing market before they could operate"},{"id":"B","text":"argue that printing was an unprofitable trade"},{"id":"C","text":"contrast printing with manuscript copying"},{"id":"D","text":"establish a chronology for the spread of the press"},{"id":"E","text":"suggest that literacy was a luxury"}]',
    'A', 'Cost is the mechanism of the argument: an expensive machine has to pay for itself, so a printer needs buyers before setting up. It is not offered as evidence that printing was unprofitable, and the passage draws no contrast with manuscripts and gives no chronology.'),

  ('verbal', 'Text completion', 'Single blank', 'medium', 'multiple_choice',
    'The results were widely reported as a breakthrough, though the authors themselves were careful to describe them as ______, pending replication in a larger sample.',
    'Select the word that best completes the text.',
    '[{"id":"A","text":"conclusive"},{"id":"B","text":"provisional"},{"id":"C","text":"unprecedented"},{"id":"D","text":"exhaustive"},{"id":"E","text":"controversial"}]',
    'B', 'The authors are contrasted with the reporting, and "pending replication" tells you what they meant: not yet settled. "Provisional" fits exactly. "Conclusive" and "exhaustive" both say the opposite, "unprecedented" is about novelty, and nothing in the sentence suggests dispute.'),

  ('verbal', 'Reading comprehension', 'Weaken', 'hard', 'multiple_choice',
    'A city reduced its speed limit on residential streets and reported a 22 percent fall in collisions the following year. Officials concluded that the lower limit caused the reduction.',
    'Which finding, if true, most weakens the officials'' conclusion?',
    '[{"id":"A","text":"Collisions fell by a similar amount in neighbouring cities that did not change their limits"},{"id":"B","text":"Some drivers exceeded the new limit"},{"id":"C","text":"The reduction was larger on some streets than on others"},{"id":"D","text":"The new limit was unpopular with commuters"},{"id":"E","text":"Enforcement of the limit increased slightly"}]',
    'A', 'If cities that changed nothing saw the same fall, the fall was produced by something affecting all of them and not by the policy -- that removes the causal link rather than merely qualifying it. Non-compliance and uneven effects are compatible with the policy working, unpopularity is irrelevant to whether it worked, and increased enforcement would if anything strengthen the case.'),

  -- ============== Quantitative Reasoning ==============

  ('quant', 'Arithmetic', 'Percentages', 'easy', 'multiple_choice',
    null,
    'A price is increased by 20 percent and then decreased by 20 percent. Compared with the original price, the final price is:',
    '[{"id":"A","text":"the same"},{"id":"B","text":"4 percent lower"},{"id":"C","text":"4 percent higher"},{"id":"D","text":"20 percent lower"},{"id":"E","text":"40 percent lower"}]',
    'B', 'The second percentage is taken of a larger number than the first, so the two do not cancel. Starting from 100: a 20 percent rise gives 120, and a 20 percent fall from 120 removes 24, leaving 96 -- 4 percent below the original. The general result is that successive equal rises and falls always end below where they started.'),

  ('quant', 'Algebra', 'Linear equations', 'easy', 'multiple_choice',
    null,
    'If 4x + 9 = 33, what is the value of 2x?',
    '[{"id":"A","text":"6"},{"id":"B","text":"12"},{"id":"C","text":"18"},{"id":"D","text":"24"},{"id":"E","text":"48"}]',
    'B', 'Subtracting 9 gives 4x = 24, so x = 6 and 2x = 12. The question asks for 2x rather than x, which is the standard way this exam catches a correct calculation that stops one step early -- choice A is the value of x.'),

  ('quant', 'Arithmetic', 'Ratios', 'medium', 'multiple_choice',
    null,
    'A mixture contains red and blue tokens in a ratio of 3 to 5. If there are 96 tokens in total, how many are blue?',
    '[{"id":"A","text":"36"},{"id":"B","text":"48"},{"id":"C","text":"56"},{"id":"D","text":"60"},{"id":"E","text":"64"}]',
    'D', 'The ratio has 3 + 5 = 8 parts, so each part is 96 / 8 = 12 tokens. Blue is 5 parts, or 60. Choice A is the number of red tokens, which is the answer to the question this one was designed to be misread as.'),

  ('quant', 'Data analysis', 'Statistics', 'medium', 'multiple_choice',
    'A data set contains the values 4, 7, 7, 9, and 23.',
    'Which statement about this data set is true?',
    '[{"id":"A","text":"The mean is less than the median"},{"id":"B","text":"The mean is greater than the median"},{"id":"C","text":"The mean equals the median"},{"id":"D","text":"The mode is greater than the mean"},{"id":"E","text":"The range is less than the mean"}]',
    'B', 'The median is the middle value of the sorted list, which is 7. The mean is (4 + 7 + 7 + 9 + 23) / 5 = 50 / 5 = 10. The single large value pulls the mean above the median without moving the median at all, which is the whole reason both measures exist.'),

  ('quant', 'Geometry', 'Circles', 'medium', 'multiple_choice',
    null,
    'A circle has an area of 36π. What is its circumference?',
    '[{"id":"A","text":"6π"},{"id":"B","text":"12π"},{"id":"C","text":"18π"},{"id":"D","text":"36π"},{"id":"E","text":"72π"}]',
    'B', 'Area is πr squared, so r squared = 36 and r = 6. Circumference is 2πr = 12π. Choice A takes the radius as the answer with a π attached, and choice D repeats the area.'),

  ('quant', 'Algebra', 'Exponents', 'medium', 'multiple_choice',
    null,
    'If 2^(x+3) = 32, what is the value of x?',
    '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"5"},{"id":"E","text":"8"}]',
    'B', 'Write 32 as a power of the same base: 32 = 2^5. With equal bases the exponents must be equal, so x + 3 = 5 and x = 2. Choice D is the exponent on the right-hand side, taken without subtracting the 3.'),

  ('quant', 'Data analysis', 'Probability', 'hard', 'multiple_choice',
    null,
    'Two fair six-sided dice are rolled. What is the probability that the sum is 7?',
    '[{"id":"A","text":"1/12"},{"id":"B","text":"1/9"},{"id":"C","text":"1/6"},{"id":"D","text":"1/4"},{"id":"E","text":"7/36"}]',
    'C', 'There are 36 equally likely outcomes, and six of them sum to 7: 1-6, 2-5, 3-4, 4-3, 5-2 and 6-1. That is 6/36, or 1/6. Counting 1-6 and 6-1 as one outcome gives 3/36 and choice A, which is the usual error -- the dice are distinguishable even when they look identical.'),

  ('quant', 'Algebra', 'Word problems', 'hard', 'student_produced_response',
    null,
    'A train travels 180 kilometres at a constant speed. If its speed had been 15 kilometres per hour faster, the journey would have taken 1 hour less. What was the train''s actual speed, in kilometres per hour?',
    null, '45', 'Let the speed be s. Then 180/s - 180/(s + 15) = 1. Multiplying through by s(s + 15) gives 180(s + 15) - 180s = s(s + 15), so 2700 = s squared + 15s. Solving s squared + 15s - 2700 = 0 factors as (s + 60)(s - 45) = 0, and speed cannot be negative, so s = 45.'),

  ('quant', 'Geometry', 'Triangles', 'hard', 'multiple_choice',
    null,
    'In a right triangle, one leg measures 8 and the hypotenuse measures 17. What is the area of the triangle?',
    '[{"id":"A","text":"30"},{"id":"B","text":"60"},{"id":"C","text":"68"},{"id":"D","text":"120"},{"id":"E","text":"136"}]',
    'B', 'The other leg is the square root of 17 squared minus 8 squared, which is the square root of 289 - 64 = 225, so 15. The area is half the product of the legs: (1/2)(8)(15) = 60. Choice D forgets the half, and choice C multiplies the given leg by the hypotenuse.'),

  ('quant', 'Data analysis', 'Interpreting data', 'medium', 'multiple_choice',
    'A company reports the following quarterly revenue, in millions of dollars:

Q1: 12
Q2: 15
Q3: 15
Q4: 18',
    'By what percent did revenue grow from Q1 to Q4?',
    '[{"id":"A","text":"6 percent"},{"id":"B","text":"33 percent"},{"id":"C","text":"50 percent"},{"id":"D","text":"60 percent"},{"id":"E","text":"150 percent"}]',
    'C', 'The increase is 18 - 12 = 6, and percent change is the increase over the ORIGINAL value: 6/12 = 0.5, or 50 percent. Choice B divides by the final value instead, and choice E reports the ratio of final to original rather than the change.')

) as v(section, domain, skill, difficulty, question_type, stimulus, question_text, answer_choices, correct_answer, explanation)
where e.slug = 'gre'
on conflict (exam_id, md5(coalesce(stimulus, '') || E'\x1f' || question_text)) do nothing;

update public.exam_definitions
set status = 'available'
where slug = 'gre'
  and exists (
    select 1 from public.diagnostic_questions q
    where q.exam_id = exam_definitions.id and q.status = 'published'
  );


-- ======================================================================
-- FILE: 20260906_07_voice_topic_tutoring.sql
-- ======================================================================

-- Calling Vyra about anything, and changing the subject mid-call.
--
-- Until now a voice session had to be grounded in a deck the student already
-- owned: loadStudyMaterial read `decks` and `questions`, and an account with
-- neither got a tutor whose prompt said "they have no material loaded". So
-- the one thing a student most wants from a tutor on a phone call -- "teach
-- me the Krebs cycle" -- was the one thing it could not do, and a new user
-- had to build a deck before the headline feature worked at all.
--
-- Two changes, both additive:
--
--   1. voice_sessions.source_type gains 'topic', for a call grounded in a
--      subject rather than in stored material.
--   2. voice_topic_concepts caches the concept set generated for a topic.
--
-- The cache is the load-bearing half. Generating concepts costs a model call
-- and roughly two seconds, which is tolerable once on a pre-call screen and
-- NOT tolerable mid-call, where the student has just said "actually, switch
-- to algebra 2" and is listening to silence. Keyed on the collapsed topic
-- key from lib/voice/topics.ts, so "Algebra 2", "algebra 2" and "let's do
-- algebra 2" are one row and one generation.
--
-- The cache is shared across users on purpose. It holds no student text: the
-- key is a normalised subject name and the value is a generic concept
-- outline for it, which is the same for everyone who asks. Nothing personal
-- goes in, so nothing personal can come out of a shared read.
--
-- Safe to run more than once.

-- ============================================================
-- voice_sessions.source_type gains 'topic'
-- ============================================================

-- The check constraint is dropped and recreated rather than altered, since
-- Postgres has no "add value to check". Named exactly as the original so a
-- database created before this migration and one created after end up with
-- the same constraint name.
alter table if exists public.voice_sessions
  drop constraint if exists voice_sessions_source_type_check;

alter table if exists public.voice_sessions
  add constraint voice_sessions_source_type_check
  check (source_type in ('deck', 'note', 'weak_topics', 'open', 'topic'));

-- Every topic worked on during the call, in order, including the one it
-- started on. A session that switched from photosynthesis to algebra is two
-- lessons and the review has to name both; before this the row could only
-- remember the title it opened with.
alter table if exists public.voice_sessions
  add column if not exists topics_covered jsonb not null default '[]'::jsonb;

comment on column public.voice_sessions.topics_covered is
  'Ordered list of topic labels taught in this call, including mid-call switches. source_title only ever held the opening one.';

-- ============================================================
-- voice_topic_concepts (generated concept cache)
-- ============================================================

create table if not exists public.voice_topic_concepts (
  id uuid primary key default gen_random_uuid(),

  -- topicKey() from lib/voice/topics.ts: lowercased, depunctuated, lead-ins
  -- stripped. The whole point is that many spellings collapse onto one row.
  topic_key text not null,

  -- Concepts for "photosynthesis" at elementary level are not the concepts
  -- for it at undergraduate level, so level is part of the identity rather
  -- than a filter applied afterwards.
  level text not null default 'unspecified',

  -- The topic as the student actually phrased it, for display. The first
  -- spelling wins; it is only ever shown back to the person who asked.
  topic_label text not null,

  -- Concept[] from lib/voice/types.ts. jsonb because its shape is owned by
  -- the tutoring code and will change with the teaching, not the schema.
  concepts jsonb not null,

  model text,
  created_at timestamptz not null default now(),
  used_at timestamptz not null default now(),
  use_count integer not null default 1,

  -- One row per (topic, level). This is what makes the cache a cache.
  constraint voice_topic_concepts_key_level_unique unique (topic_key, level)
);

-- The read path on every call start and every mid-call switch is an exact
-- lookup on (topic_key, level), which the unique constraint already indexes.
-- This one is for the eviction/refresh sweep: least recently used first.
create index if not exists voice_topic_concepts_used_idx
  on public.voice_topic_concepts (used_at);

alter table if exists public.voice_topic_concepts enable row level security;

-- No policy of any kind, deliberately.
--
-- With RLS on and no policy, the anon and authenticated roles can neither
-- read nor write this table; only the service-role client can, which is the
-- same shape used for every other table the browser has no business
-- touching. A student reaches these concepts through
-- /api/vyra/topic-concepts, which is authenticated and rate limited --
-- direct client access would be an uncapped, unauthenticated way to spend
-- money on model calls.

comment on table public.voice_topic_concepts is
  'Cache of AI-generated concept outlines per (topic, level), so a mid-call topic switch does not cost a model round trip. Contains no student text. Service-role only.';
comment on column public.voice_topic_concepts.topic_key is
  'topicKey() from lib/voice/topics.ts. Collapses spelling, case, punctuation and spoken lead-ins onto one key.';


