-- Run this to confirm. Five rows, all 'available', with these counts.
-- Anything lower means a bank did not land.
--
--   select e.slug, e.status, count(q.id) as published
--   from public.exam_definitions e
--   left join public.diagnostic_questions q
--     on q.exam_id = e.id and q.status = 'published'
--   group by e.slug, e.status
--   order by published desc;
--
--   digital-sat  available  98
--   act          available  60
--   nclex-rn     available  57
--   mcat         available  24
--   gre          available  20
--
-- The other four rows (psat-nmsqt, lsat, ap-exams, nclex-pn) stay
-- 'coming_soon' with zero questions. That is correct: there is no bank
-- behind them, and /exams says so rather than offering practice.
